static bool is_perfect_square(long long n)
{
    if (n < 0) {
        return false;
    }
    if (n < 2) {
        return true;
    }

    long long low = 1;
    long long high = n / 2;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        long long quotient = n / mid;

        if (mid <= quotient) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    long long root = low - 1;
    return root * root == n;
}

