static char *read_line(void)
{
    size_t cap = 128;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        return NULL;
    }

    int c;
    while ((c = fgetc(stdin)) != EOF && c != '\n') {
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (tmp == NULL) {
                free(buf);
                return NULL;
            }
            buf = tmp;
        }
        buf[len++] = (char)c;
    }

    if (len > 0 && buf[len - 1] == '\r') {
        len--;
    }
    buf[len] = '\0';
    return buf;
}

int main(void)
{
    char *line = read_line();
    if (line == NULL) {
        return 1;
    }

    size_t len = 0;
    while (line[len] != '\0') {
        len++;
    }

    size_t left = 0;
    size_t right = len;
    int is_palindrome = 1;

    while (left < right) {
        while (left < right && line[left] == ' ') {
            left++;
        }
        while (left < right && line[right - 1] == ' ') {
            right--;
        }
        if (left >= right) {
            break;
        }
        if (line[left] != line[right - 1]) {
            is_palindrome = 0;
            break;
        }
        left++;
        right--;
    }

    printf("%d\n", is_palindrome);
    free(line);
    return 0;
}

