#include <ctype.h>
#include <stdio.h>

int main(void)
{
    int ch;
    int ok = 1;
    int saw_newline = 0;

    while ((ch = getchar()) != EOF) {
        if (ch == '\n') {
            if (saw_newline) {
                ok = 0;
            }
            saw_newline = 1;
        } else if (saw_newline) {
            ok = 0;
        } else if (!isdigit((unsigned char)ch)) {
            ok = 0;
        }
    }

    printf("%d\n", ok);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static void bubble_sort(int *a, size_t n)
{
    for (size_t i = 0; i + 1 < n; ++i) {
        int swapped = 0;
        for (size_t j = 0; j + 1 < n - i; ++j) {
            if (a[j] > a[j + 1]) {
                int tmp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = tmp;
                swapped = 1;
            }
        }
        if (!swapped) {
            break;
        }
    }
}

int main(void)
{
    int n;
    if (scanf("%d", &n) != 1 || n < 0) {
        return EXIT_FAILURE;
    }

    int *a = NULL;
    if (n > 0) {
        a = malloc((size_t)n * sizeof *a);
        if (a == NULL) {
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            free(a);
            return EXIT_FAILURE;
        }
    }

    bubble_sort(a, (size_t)n);

    for (int i = 0; i < n; ++i) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", a[i]);
    }
    if (n > 0) {
        putchar('\n');
    }

    free(a);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return EXIT_FAILURE;
    }

    int *values = n > 0 ? malloc((size_t)n * sizeof *values) : NULL;
    if (n > 0 && values == NULL) {
        return EXIT_FAILURE;
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &values[i]) != 1) {
            free(values);
            return EXIT_FAILURE;
        }
    }

    for (int i = 1; i < n; ++i) {
        int key = values[i];
        int j = i - 1;

        while (j >= 0 && values[j] > key) {
            values[j + 1] = values[j];
            --j;
        }
        values[j + 1] = key;
    }

    for (int i = 0; i < n; ++i) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", values[i]);
    }
    putchar('\n');

    free(values);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return EXIT_FAILURE;
    }

    size_t count = (size_t)n;
    int *values = count ? malloc(count * sizeof *values) : NULL;

    if (count && values == NULL) {
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < count; ++i) {
        if (scanf("%d", &values[i]) != 1) {
            free(values);
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i + 1 < count; ++i) {
        size_t minimum = i;
        for (size_t j = i + 1; j < count; ++j) {
            if (values[j] < values[minimum]) {
                minimum = j;
            }
        }
        if (minimum != i) {
            int temporary = values[i];
            values[i] = values[minimum];
            values[minimum] = temporary;
        }
    }

    for (size_t i = 0; i < count; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        printf("%d", values[i]);
    }
    putchar('\n');

    free(values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static void quicksort(int *a, int lo, int hi)
{
    if (hi - lo < 2)
        return;

    int pivot = a[lo + (hi - lo) / 2];
    int i = lo - 1;
    int j = hi;

    for (;;) {
        do {
            ++i;
        } while (a[i] < pivot);
        do {
            --j;
        } while (a[j] > pivot);

        if (i >= j)
            break;

        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }

    quicksort(a, lo, j + 1);
    quicksort(a, j + 1, hi);
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0)
        return 1;

    int *values = NULL;
    if (n > 0) {
        values = malloc((size_t)n * sizeof *values);
        if (values == NULL)
            return 1;

        for (int i = 0; i < n; ++i) {
            if (scanf("%d", &values[i]) != 1) {
                free(values);
                return 1;
            }
        }
    }

    quicksort(values, 0, n);

    for (int i = 0; i < n; ++i)
        printf("%d%c", values[i], i + 1 < n ? ' ' : '\n');

    free(values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static void merge(int *a, int *tmp, size_t left, size_t mid, size_t right)
{
    size_t i = left, j = mid, k = left;

    while (i < mid && j < right) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
        }
    }
    while (i < mid) {
        tmp[k++] = a[i++];
    }
    while (j < right) {
        tmp[k++] = a[j++];
    }
    for (k = left; k < right; ++k) {
        a[k] = tmp[k];
    }
}

static void merge_sort_range(int *a, int *tmp, size_t left, size_t right)
{
    if (right - left < 2) {
        return;
    }

    size_t mid = left + (right - left) / 2;
    merge_sort_range(a, tmp, left, mid);
    merge_sort_range(a, tmp, mid, right);
    merge(a, tmp, left, mid, right);
}

