#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int value;
    struct node *next;
} node;

static node *new_node(int value)
{
    node *n = malloc(sizeof *n);
    if (n == NULL) {
        return NULL;
    }
    n->value = value;
    n->next = NULL;
    return n;
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        fprintf(stderr, "error: invalid element count\n");
        return 1;
    }

    node *head = NULL;
    node *tail = NULL;
    int status = 0;

    for (int i = 0; i < n; ++i) {
        int value;

        if (scanf("%d", &value) != 1) {
            fprintf(stderr, "error: invalid input\n");
            status = 1;
            goto cleanup_list;
        }

        node *created = new_node(value);
        if (created == NULL) {
            fprintf(stderr, "error: out of memory\n");
            status = 1;
            goto cleanup_list;
        }

        if (tail != NULL) {
            tail->next = created;
        } else {
            head = created;
        }
        tail = created;
    }

    node **stack = NULL;
    if (n > 0) {
        stack = malloc((size_t)n * sizeof *stack);
        if (stack == NULL) {
            fprintf(stderr, "error: out of memory\n");
            status = 1;
            goto cleanup_list;
        }
    }

    size_t count = 0;
    for (node *current = head; current != NULL; current = current->next) {
        stack[count++] = current;
    }

    int first = 1;
    while (count > 0) {
        node *current = stack[--count];
        if (!first) {
            putchar(' ');
        }
        first = 0;
        printf("%d", current->value);
    }
    putchar('\n');

cleanup_stack:
    free(stack);

cleanup_list:
    while (head != NULL) {
        node *next = head->next;
        free(head);
        head = next;
    }

    return status;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int value;
    struct node *next;
} node_t;

static node_t *reverse_list(node_t *head)
{
    node_t *previous = NULL;

    while (head != NULL) {
        node_t *next = head->next;
        head->next = previous;
        previous = head;
        head = next;
    }

    return previous;
}

static void free_list(node_t *head)
{
    while (head != NULL) {
        node_t *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
        fprintf(stderr, "error: expected a non-negative count\n");
        return EXIT_FAILURE;
    }

    node_t *head = NULL;
    node_t *tail = NULL;

    for (int i = 0; i < count; ++i) {
        int value;

        if (scanf("%d", &value) != 1) {
            fprintf(stderr, "error: expected %d integers\n", count);
            free_list(head);
            return EXIT_FAILURE;
        }

        node_t *node = malloc(sizeof *node);
        if (node == NULL) {
            perror("malloc");
            free_list(head);
            return EXIT_FAILURE;
        }

        node->value = value;
        node->next = NULL;

        if (tail == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    head = reverse_list(head);

    for (const node_t *current = head; current != NULL; current = current->next) {
        if (current != head) {
            putchar(' ');
        }
        printf("%d", current->value);
    }
    putchar('\n');

    free_list(head);
    return EXIT_SUCCESS;
}

