typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

static Node *new_node(int value)
{
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static void insert(Node **root, int value)
{
    Node **current = root;
    while (*current != NULL) {
        if (value < (*current)->value)
            current = &(*current)->left;
        else
            current = &(*current)->right;
    }
    *current = new_node(value);
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1)
        return 0;
    if (n < 0)
        n = 0;

    Node *root = NULL;

    for (int i = 0; i < n; ++i) {
        int value;
        if (scanf("%d", &value) != 1)
            break;
        insert(&root, value);
    }

    size_t capacity = n > 0 ? (size_t)n : 1;
    Node **stack = malloc(capacity * sizeof *stack);
    if (stack == NULL) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    Node *current = root;
    size_t top = 0;
    int first = 1;

    while (current != NULL || top > 0) {
        while (current != NULL) {
            stack[top++] = current;
            current = current->left;
        }

        current = stack[--top];

        if (!first)
            putchar(' ');
        first = 0;
        printf("%d", current->value);

        current = current->right;
    }

    if (!first)
        putchar('\n');

    top = 0;
    if (root != NULL)
        stack[top++] = root;

    while (top > 0) {
        Node *node = stack[--top];
        if (node->left != NULL)
            stack[top++] = node->left;
        if (node->right != NULL)
            stack[top++] = node->right;
        free(node);
    }

    free(stack);
    return 0;
}

#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

#define STACK_CAPACITY 100

typedef struct {
    int items[STACK_CAPACITY];
    size_t count;
} IntStack;

static bool stack_push(IntStack *stack, int value)
{
    if (stack->count == STACK_CAPACITY) {
        return false;
    }
    stack->items[stack->count++] = value;
    return true;
}

static bool stack_pop(IntStack *stack, int *value)
{
    if (stack->count == 0) {
        return false;
    }
    *value = stack->items[--stack->count];
    return true;
}

int main(void)
{
    IntStack stack = { .count = 0 };
    char command;

    while (scanf(" %c", &command) == 1) {
        switch (command) {
            case 'p': {
                int value;
                if (scanf("%d", &value) != 1) {
                    fprintf(stderr, "error: expected an integer after 'p'\n");
                    return EXIT_FAILURE;
                }
                if (!stack_push(&stack, value)) {
                    fprintf(stderr, "error: stack overflow\n");
                    return EXIT_FAILURE;
                }
                break;
            }
            case 'o': {
                int value;
                if (!stack_pop(&stack, &value)) {
                    fprintf(stderr, "error: stack underflow\n");
                    return EXIT_FAILURE;
                }
                printf("%d\n", value);
                break;
            }
            case 'q':
                return EXIT_SUCCESS;
            default:
                fprintf(stderr, "error: unknown command '%c'\n", command);
                return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

#define QUEUE_CAPACITY 100

typedef struct {
    int data[QUEUE_CAPACITY];
    size_t head;
    size_t tail;
    size_t count;
} IntQueue;

static void queue_init(IntQueue *queue) {
    queue->head = 0;
    queue->tail = 0;
    queue->count = 0;
}

static bool queue_is_empty(const IntQueue *queue) {
    return queue->count == 0;
}

static bool queue_is_full(const IntQueue *queue) {
    return queue->count == QUEUE_CAPACITY;
}

static bool enqueue(IntQueue *queue, int value) {
    if (queue_is_full(queue)) {
        return false;
    }

    queue->data[queue->tail] = value;
    queue->tail = (queue->tail + 1) % QUEUE_CAPACITY;
    ++queue->count;
    return true;
}

static bool dequeue(IntQueue *queue, int *value) {
    if (queue_is_empty(queue)) {
        return false;
    }

    *value = queue->data[queue->head];
    queue->head = (queue->head + 1) % QUEUE_CAPACITY;
    --queue->count;
    return true;
}

int main(void) {
    IntQueue queue;
    queue_init(&queue);

    char command;
    while (scanf(" %c", &command) == 1) {
        switch (command) {
            case 'e': {
                int value;
                if (scanf("%d", &value) != 1) {
                    fprintf(stderr, "invalid enqueue command\n");
                    return EXIT_FAILURE;
                }
                if (!enqueue(&queue, value)) {
                    fprintf(stderr, "queue full\n");
                }
                break;
            }
            case 'd': {
                int value;
                if (!dequeue(&queue, &value)) {
                    fprintf(stderr, "queue empty\n");
                } else {
                    printf("%d\n", value);
                }
                break;
            }
            case 'q':
                return 0;
            default:
                fprintf(stderr, "unknown command: %c\n", command);
                break;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    char value;
    struct node *next;
} node;

static node *node_create(char value)
{
    node *n = malloc(sizeof *n);
    if (n == NULL) {
        return NULL;
    }
    n->value = value;
    n->next = NULL;
    return n;
}

static void list_free(node *head)
{
    while (head != NULL) {
        node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    node *head = NULL;
    node *tail = NULL;
    int c;

    while ((c = getchar()) != EOF) {
        node *n = node_create((char)c);
        if (n == NULL) {
            perror("malloc");
            list_free(head);
            return EXIT_FAILURE;
        }

        if (tail != NULL) {
            tail->next = n;
        } else {
            head = n;
        }
        tail = n;

        if (c == '\n') {
            break;
        }
    }

    if (ferror(stdin)) {
        perror("getchar");
        list_free(head);
        return EXIT_FAILURE;
    }

    for (node *p = head; p != NULL; p = p->next) {
        if (putchar(p->value) == EOF) {
            perror("putchar");
            list_free(head);
            return EXIT_FAILURE;
        }
    }

    list_free(head);
    return EXIT_SUCCESS;
}

#include <stdio.h>

#define STACK_CAPACITY 256

int main(void)
{
    int stack[STACK_CAPACITY];
    size_t top = 0;
    int c;

    while ((c = getchar()) != '\n' && c != EOF) {
        if (c == ' ' || c == '\t' || c == '\r') {
            continue;
        }

        if (c >= '0' && c <= '9') {
            if (top == STACK_CAPACITY) {
                fprintf(stderr, "stack overflow\n");
                return 1;
            }
            stack[top++] = c - '0';
        } else if (c == '+' || c == '-' || c == '*' || c == '/') {
            if (top < 2) {
                fprintf(stderr, "invalid expression\n");
                return 1;
            }

            int right = stack[--top];
            int left = stack[--top];
            int result;

            switch (c) {
                case '+': result = left + right; break;
                case '-': result = left - right; break;
                case '*': result = left * right; break;
                case '/':
                    if (right == 0) {
                        fprintf(stderr, "division by zero\n");
                        return 1;
                    }
                    result = left / right;
                    break;
                default:
                    fprintf(stderr, "invalid operator\n");
                    return 1;
            }

            stack[top++] = result;
        } else {
            fprintf(stderr, "invalid character\n");
            return 1;
        }
    }

    if (top != 1) {
        fprintf(stderr, "invalid expression\n");
        return 1;
    }

    printf("%d\n", stack[0]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static char *read_all_stdin(void)
{
    size_t capacity = 1024;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int c;
    while ((c = fgetc(stdin)) != EOF) {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity * 2;
            char *grown = realloc(buffer, new_capacity);

            if (grown == NULL) {
                free(buffer);
                return NULL;
            }

            buffer = grown;
            capacity = new_capacity;
        }

        buffer[length++] = (char)c;
    }

    buffer[length] = '\0';
    return buffer;
}

int main(void)
{
    char *input = read_all_stdin();

    if (input == NULL) {
        fprintf(stderr, "out of memory\n");
        return EXIT_FAILURE;
    }

    const char *p = input;

    while (isspace((unsigned char)*p)) {
        ++p;
    }

    int negative = 0;
    if (*p == '+' || *p == '-') {
        if (*p == '-') {
            negative = 1;
        }
        ++p;
    }

    while (isspace((unsigned char)*p)) {
        ++p;
    }

    if (!isdigit((unsigned char)*p)) {
        fprintf(stderr, "invalid expression\n");
        free(input);
        return EXIT_FAILURE;
    }

    long long result = 0;
    while (isdigit((unsigned char)*p)) {
        result = result * 10 + (*p - '0');
        ++p;
    }

    if (negative) {
        result = -result;
    }

    while (1) {
        while (isspace((unsigned char)*p)) {
            ++p;
        }

        if (*p == '\0') {
            break;
        }

        if (*p != '+' && *p != '-') {
            fprintf(stderr, "invalid expression\n");
            free(input);
            return EXIT_FAILURE;
        }

        int subtract = (*p == '-');
        ++p;

        while (isspace((unsigned char)*p)) {
            ++p;
        }

        if (!isdigit((unsigned char)*p)) {
            fprintf(stderr, "invalid expression\n");
            free(input);
            return EXIT_FAILURE;
        }

        long long value = 0;
        while (isdigit((unsigned char)*p)) {
            value = value * 10 + (*p - '0');
            ++p;
        }

        if (subtract) {
            result -= value;
        } else {
            result += value;
        }
    }

    printf("%lld\n", result);
    free(input);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *read_line(void)
{
    size_t capacity = 128;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *tmp = realloc(buffer, capacity);
            if (tmp == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = tmp;
        }
        buffer[length++] = (char)ch;
    }

    if (length == 0 && ch == EOF) {
        free(buffer);
        return NULL;
    }

    buffer[length] = '\0';
    return buffer;
}

static int compare_words(const void *left, const void *right)
{
    const char *const *a = left;
    const char *const *b = right;
    return strcmp(*a, *b);
}

int main(void)
{
    char *line = read_line();
    if (line == NULL) {
        return 0;
    }

    static const char *delimiters = " \t\r\n\v\f";

    size_t count = 0;
    char *copy = malloc(strlen(line) + 1);
    if (copy == NULL) {
        free(line);
        return EXIT_FAILURE;
    }
    strcpy(copy, line);

    for (char *token = strtok(copy, delimiters);
         token != NULL;
         token = strtok(NULL, delimiters)) {
        ++count;
    }
    free(copy);

    if (count == 0) {
        free(line);
        putchar('\n');
        return 0;
    }

    char **words = malloc(count * sizeof *words);
    if (words == NULL) {
        free(line);
        return EXIT_FAILURE;
    }

    size_t index = 0;
    for (char *token = strtok(line, delimiters);
         token != NULL && index < count;
         token = strtok(NULL, delimiters)) {
        words[index++] = token;
    }

    qsort(words, count, sizeof *words, compare_words);

    for (size_t i = 0; i < count; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        fputs(words[i], stdout);
    }
    putchar('\n');

    free(words);
    free(line);
    return 0;
}

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

static int roman_value(char c)
{
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default: return -1;
    }
}

int main(void)
{
    size_t capacity = 4096;
    size_t length = 0;
    char *input = malloc(capacity);

    if (input == NULL) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    int c;
    while ((c = getchar()) != EOF) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *tmp = realloc(input, capacity);
            if (tmp == NULL) {
                perror("realloc");
                free(input);
                return EXIT_FAILURE;
            }
            input = tmp;
        }
        input[length++] = (char)c;
    }
    input[length] = '\0';

    size_t count = 0;
    for (size_t i = 0; i < length; i++) {
        unsigned char uc = (unsigned char)input[i];
        if (isspace(uc)) {
            continue;
        }

        char ch = (char)toupper(uc);
        if (roman_value(ch) < 0) {
            fprintf(stderr, "invalid Roman numeral: %c\n", input[i]);
            free(input);
            return EXIT_FAILURE;
        }
        input[count++] = ch;
    }
    input[count] = '\0';

    long long value = 0;
    for (size_t i = 0; i < count; i++) {
        int current = roman_value(input[i]);
        int next = (i + 1 < count) ? roman_value(input[i + 1]) : 0;

        if (current < next) {
            value -= current;
        } else {
            value += current;
        }
    }

    printf("%lld\n", value);
    free(input);
    return EXIT_SUCCESS;
}

