#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "error: expected an integer\n");
        return EXIT_FAILURE;
    }
    if (n < 0) {
        fprintf(stderr, "error: n must be non-negative\n");
        return EXIT_FAILURE;
    }
    if (n == 0) {
        return EXIT_SUCCESS;
    }

    size_t count = (size_t)n * (size_t)n;
    int *matrix = calloc(count, sizeof *matrix);
    if (matrix == NULL) {
        fprintf(stderr, "error: out of memory\n");
        return EXIT_FAILURE;
    }

    int top = 0, bottom = n - 1;
    int left = 0, right = n - 1;
    int value = 1;

    while (top <= bottom && left <= right) {
        for (int col = left; col <= right; ++col)
            matrix[top * n + col] = value++;
        ++top;

        for (int row = top; row <= bottom; ++row)
            matrix[row * n + right] = value++;
        --right;

        if (top <= bottom) {
            for (int col = right; col >= left; --col)
                matrix[bottom * n + col] = value++;
            --bottom;
        }

        if (left <= right) {
            for (int row = bottom; row >= top; --row)
                matrix[row * n + left] = value++;
            ++left;
        }
    }

    for (int row = 0; row < n; ++row) {
        for (int col = 0; col < n; ++col) {
            if (col != 0)
                putchar(' ');
            printf("%d", matrix[row * n + col]);
        }
        putchar('\n');
    }

    free(matrix);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *next_term(const char *current) {
    size_t length = strlen(current);
    char *next = malloc(2 * length + 1);
    if (next == NULL) {
        return NULL;
    }

    size_t position = 0;
    size_t index = 0;
    while (index < length) {
        char digit = current[index];
        size_t run_end = index;
        while (run_end < length && current[run_end] == digit) {
            ++run_end;
        }
        size_t count = run_end - index;

        char count_text[32];
        int count_length = snprintf(count_text, sizeof count_text, "%zu", count);
        if (count_length < 0) {
            free(next);
            return NULL;
        }

        memcpy(next + position, count_text, (size_t)count_length);
        position += (size_t)count_length;
        next[position++] = digit;

        index = run_end;
    }

    next[position] = '\0';
    return next;
}

int main(void) {
    int term_count;
    if (scanf("%d", &term_count) != 1 || term_count < 0) {
        return EXIT_FAILURE;
    }

    char *term = malloc(2);
    if (term == NULL) {
        return EXIT_FAILURE;
    }
    term[0] = '1';
    term[1] = '\0';

    for (int i = 0; i < term_count; ++i) {
        if (puts(term) == EOF) {
            free(term);
            return EXIT_FAILURE;
        }
        if (i + 1 < term_count) {
            char *following = next_term(term);
            if (following == NULL) {
                free(term);
                return EXIT_FAILURE;
            }
            free(term);
            term = following;
        }
    }

    free(term);
    return 0;
}

