#include <stdio.h>

typedef long long (*transform_fn)(long long);

static long long transform_abs(long long value)
{
    return value < 0 ? -value : value;
}

static long long transform_square(long long value)
{
    return value * value;
}

static long long transform_negate(long long value)
{
    return -value;
}

int main(void)
{
    char command;

    if (scanf(" %c", &command) != 1) {
        return 0;
    }

    transform_fn apply = NULL;

    switch (command) {
        case 'a':
            apply = transform_abs;
            break;
        case 's':
            apply = transform_square;
            break;
        case 'n':
            apply = transform_negate;
            break;
        default:
            fprintf(stderr, "unknown command: %c\n", command);
            return 1;
    }

    long long value;
    while (scanf("%lld", &value) == 1) {
        printf("%lld\n", apply(value));
    }

    return 0;
}

