#include <stdio.h>

static unsigned long long mulmod(unsigned long long a, unsigned long long b, unsigned long long m) {
    return (unsigned long long)((__int128)a * b % m);
}

static unsigned long long powmod(unsigned long long a, unsigned long long e, unsigned long long m) {
    unsigned long long r = 1 % m;
    a %= m;
    while (e > 0) {
        if (e & 1) r = mulmod(r, a, m);
        a = mulmod(a, a, m);
        e >>= 1;
    }
    return r;
}

static int is_prime(long long n) {
    if (n < 2) return 0;
    unsigned long long x = (unsigned long long)n;

    /* Small primes and even numbers. */
    if (x < 4) return 1;
    if (x % 2 == 0) return 0;

    /* Write x-1 = d * 2^s with d odd. */
    unsigned long long d = x - 1;
    int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    /* Deterministic Miller-Rabin bases for all 64-bit integers. */
    static const unsigned long long bases[] = {
        2ULL, 325ULL, 9375ULL, 28178ULL, 450775ULL, 9780504ULL, 1795265022ULL
    };

    for (size_t i = 0; i < sizeof(bases) / sizeof(bases[0]); ++i) {
        unsigned long long a = bases[i] % x;
        if (a == 0) continue; /* base is a multiple of x; skip */
        unsigned long long y = powmod(a, d, x);
        if (y == 1 || y == x - 1) continue;
        int composite = 1;
        for (int r = 1; r < s; ++r) {
            y = mulmod(y, y, x);
            if (y == x - 1) {
                composite = 0;
                break;
            }
        }
        if (composite) return 0;
    }
    return 1;
}

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;
    printf("%d\n", is_prime(n));
    return 0;
}

