#define MAX_N 1000000

/* Fixed-size sieve array: 1 means "still candidate prime". */
static unsigned char sieve[MAX_N + 1];

int main(void) {
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }

    /* Cap to array bounds so we never overflow the fixed buffer. */
    if (n > MAX_N) {
        n = MAX_N;
    }
    if (n < 2) {
        return 0;
    }

    /* Initially every number >= 2 is a candidate. */
    for (int i = 2; i <= n; i++) {
        sieve[i] = 1;
    }
    sieve[0] = sieve[1] = 0;

    /* Sieve: for each prime i, cross off its multiples starting at i*i.
       Starting at i*i is safe because smaller multiples were already
       crossed off by smaller prime factors. */
    for (int i = 2; (long long)i * i <= n; i++) {
        if (sieve[i]) {
            for (int j = i * i; j <= n; j += i) {
                sieve[j] = 0;
            }
        }
    }

    /* Print surviving candidates. */
    int first = 1;
    for (int i = 2; i <= n; i++) {
        if (sieve[i]) {
            if (!first) {
                putchar(' ');
            }
            printf("%d", i);
            first = 0;
        }
    }
    if (!first) {
        putchar('\n');
    }

    return 0;
}

