    if (scanf("%lld", &n) != 1) {
        return 0;
    }

    /* Convert to unsigned so negating LLONG_MIN cannot overflow. */
    unsigned long long value = (n < 0)
        ? (unsigned long long)(-(n + 1)) + 1ULL
        : (unsigned long long)n;

    unsigned long long reversed = 0;

    /* Trailing zeros in the original number vanish naturally. */
    while (value != 0) {
        reversed = reversed * 10ULL + (value % 10ULL);
        value /= 10ULL;
    }

    /* Reapply the sign. Zero needs no special handling. */
    if (n < 0) {
        printf("%lld\n", -(long long)reversed);
    } else {
        printf("%lld\n", (long long)reversed);
    }

