        putchar('-');
        /* Casting first makes LLONG_MIN safe: -(unsigned long long)n. */
        x = -(unsigned long long)n;
    } else {
        x = (unsigned long long)n;
    }

    /* Zero is a special case because no set bit exists. */
    if (x == 0) {
        puts("0");
        return 0;
    }

    int started = 0;

    /* Start at the highest possible bit and skip leading zeros. */
    for (unsigned long long mask = 1ULL << 63; mask != 0; mask >>= 1) {
        if (x & mask) {
            putchar('1');
            started = 1;
        } else if (started) {
            putchar('0');
        }
    }

    putchar('\n');
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

/* Read all of stdin into one malloc'd, NUL-terminated buffer. */
static char *read_all_stdin(void) {
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    if (!buf) return NULL;

    for (;;) {
        if (len == cap) {
            if (cap > (size_t)-1 / 2) { free(buf); return NULL; }
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) { free(buf); return NULL; }
            buf = tmp;
        }
        size_t got = fread(buf + len, 1, cap - len, stdin);
        len += got;
        if (got == 0) {
            if (ferror(stdin)) { free(buf); return NULL; }
            break;
        }
    }

    /* Make room for the terminating NUL even when len == cap. */
    char *result = realloc(buf, len + 1);
    if (!result) { free(buf); return NULL; }
    result[len] = '\0';
    return result;
}

int main(void) {
    char *input = read_all_stdin();
    if (!input) return 0;

    /* Skip whitespace and an optional leading '+'. */
    char *p = input;
    while (isspace((unsigned char)*p)) p++;
    if (*p == '+') p++;

    char *num = p;
    while (isdigit((unsigned char)*p)) p++;

    /* No digits found: treat as zero. */
    if (p == num) {
        puts("0");
        free(input);
        return 0;
    }

    size_t nlen = (size_t)(p - num);

    /* Remove leading zeros, but keep one digit if the value is zero. */
    while (nlen > 1 && *num == '0') { num++; nlen--; }

    size_t count = 0;

    /* Repeatedly divide the decimal string by 2. Each remainder is one bit. */
    while (!(nlen == 1 && *num == '0')) {
        int carry = 0;
        for (size_t i = 0; i < nlen; i++) {
            int value = carry * 10 + (num[i] - '0');
            num[i] = (char)('0' + value / 2); /* quotient digit */
            carry = value % 2;                  /* remainder */
        }
        count += (size_t)carry;

        /* Strip zeros created at the front by division. */
        while (nlen > 1 && *num == '0') { num++; nlen--; }
    }

    printf("%zu\n", count);
    free(input);
    return 0;
}

#include <stdio.h>

/* Safe modular addition: (x + y) mod m without overflow. */
static unsigned long long addmod(unsigned long long x, unsigned long long y,
                                unsigned long long m) {
    x %= m;
    y %= m;
    if (x >= m - y) {          /* x + y >= m, so subtract m */
        return x - (m - y);
    }
    return x + y;
}

/* Safe modular multiplication using binary method. */
static unsigned long long mulmod(unsigned long long a, unsigned long long b,
                                unsigned long long m) {
    unsigned long long r = 0;
    a %= m;
    while (b > 0) {
        if (b & 1ULL) {
            r = addmod(r, a, m);
        }
        a = addmod(a, a, m);
        b >>= 1ULL;
    }
    return r;
}

/* Fast modular exponentiation: a^b mod m. */
static unsigned long long powmod(long long a, long long b, long long m) {
    if (m == 1) return 0;

    unsigned long long mod = (unsigned long long)m;

    /* Normalize base into [0, m). */
    long long r = a % (long long)mod;
    if (r < 0) r += (long long)mod;
    unsigned long long base = (unsigned long long)r;

    unsigned long long exp = (unsigned long long)b;
    unsigned long long result = 1 % mod;

    while (exp > 0) {
        if (exp & 1ULL) {
            result = mulmod(result, base, mod);
        }
        base = mulmod(base, base, mod);
        exp >>= 1ULL;
    }
    return result;
}

int main(void) {
    long long a, b, m;

    if (scanf("%lld %lld %lld", &a, &b, &m) != 3) {
        return 0;
    }
    if (m <= 0 || b < 0) {
        return 0;
    }

    printf("%llu\n", powmod(a, b, m));
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;

    if (scanf("%lld", &n) != 1) {
        return 0;
    }

    /* Work with the magnitude so negative inputs are handled safely. */
    unsigned long long m = (n < 0) ? (0ULL - (unsigned long long)n)
                                    : (unsigned long long)n;

    if (m <= 1) {
        printf("0\n");
        return 0;
    }

    unsigned long long sum = 0;

    /* Use i <= m / i instead of i * i <= m to avoid overflow. */
    for (unsigned long long i = 1; i <= m / i; ++i) {
        if (m % i == 0) {
            sum += i;
            unsigned long long other = m / i;
            if (other != i) {
                sum += other;
            }
        }
    }

    /* Remove n itself, since all divisor pairs include m/1 = m. */
    sum -= m;

    printf("%llu\n", sum);
    return 0;
}

#include <stdio.h>

int main(void) {
    unsigned long long n;

    /* Read the starting value. Reject non-positive input. */
    if (scanf("%llu", &n) != 1 || n == 0) {
        return 0;
    }

    /* Count the first term, then apply Collatz steps until reaching 1. */
    unsigned long long length = 1;
    while (n != 1) {
        if (n % 2 == 0) {
            n /= 2;          /* Even: divide by two. */
        } else {
            n = n * 3 + 1;   /* Odd: 3n + 1. */
        }
        ++length;
    }

    /* length includes both the starting value and the final 1. */
    printf("%llu\n", length);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long input;

    if (scanf("%lld", &input) != 1) {
        return 0;
    }

    /* Euler's totient is defined for positive integers. */
    if (input <= 0) {
        printf("0\n");
        return 0;
    }

    unsigned long long n = (unsigned long long)input;
    unsigned long long result = n;   /* Start with phi(n) = n, then remove factors. */
    unsigned long long remaining = n;

    /* Trial division. Handle 2 separately, then only odd divisors. */
    if (remaining % 2 == 0) {
        while (remaining % 2 == 0) {
            remaining /= 2;
        }
        result -= result / 2;
    }

    for (unsigned long long p = 3; p * p <= remaining; p += 2) {
        if (remaining % p == 0) {
            while (remaining % p == 0) {
                remaining /= p;
            }
            /* If p divides n, multiply result by (1 - 1/p). */
            result -= result / p;
        }
    }

    /* Any remaining factor greater than 1 is prime. */
    if (remaining > 1) {
        result -= result / remaining;
    }

    printf("%llu\n", result);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a, b;

    /* Read the base and exponent from standard input. */
    if (scanf("%d %d", &a, &b) != 2) {
        return 1;
    }

    /*
     * Repeated multiplication. b is assumed to be a small nonnegative
     * exponent; the loop runs b times. Using long long for the result
     * gives a little more room before overflow than int.
     */
    long long result = 1;
    long long base = a;

    for (int i = 0; i < b; ++i) {
        result *= base;
    }

    printf("%lld\n", result);
    return 0;
}

#include <stdio.h>

/* Return floor(sqrt(n)) using only integer arithmetic.
   The comparison mid <= n / mid is equivalent to mid*mid <= n,
   but avoids overflow because no multiplication is performed. */
static long long isqrt_floor(long long n)
{
    if (n < 0) {
        return -1;
    }
    if (n < 2) {
        return n;
    }

    long long lo = 1;
    long long hi = n / 2;   /* sqrt(n) <= n/2 for n >= 4 */
    long long ans = 1;

    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;

        if (mid <= n / mid) {   /* mid*mid <= n */
            ans = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    return ans;
}

int main(void)
{
    long long n;

    if (scanf("%lld", &n) != 1) {
        return 0;
    }

    int is_perfect_square = 0;

    if (n >= 0) {
        long long r = isqrt_floor(n);
        /* r is at most sqrt(LLONG_MAX), so r*r cannot overflow. */
        is_perfect_square = (r * r == n);
    }

    printf("%d\n", is_perfect_square);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long n;

    if (scanf("%lld", &n) != 1) {
        return 0;
    }

    /* No positive power of two is <= 0 or a negative number. */
    if (n < 1) {
        printf("0\n");
        return 0;
    }

    unsigned long long x = (unsigned long long)n;
    unsigned long long p = 1;

    /* Keep doubling while the next power of two would still not exceed x. */
    while (p <= x / 2) {
        p *= 2;
    }

    printf("%llu\n", p);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t capacity = 0;
    size_t length = 0;
    char *buffer = NULL;
    int saw_newline = 0;
    int c;

    /* Read one line, growing the buffer as needed. */
    while ((c = fgetc(stdin)) != EOF) {
        if (c == '\n') {
            saw_newline = 1;
            break;
        }

        if (length == capacity) {
            size_t new_capacity = capacity ? capacity * 2 : 128;
            char *new_buffer = realloc(buffer, new_capacity);
            if (new_buffer == NULL) {
                free(buffer);
                return 1;
            }
            buffer = new_buffer;
            capacity = new_capacity;
        }

        buffer[length++] = (char)c;
    }

    /* Reverse the stored characters in place. */
    for (size_t i = 0, j = length; i < j; ) {
        char tmp = buffer[i];
        buffer[i++] = buffer[--j];
        buffer[j] = tmp;
    }

    /* Print the reversed line, preserving whether it ended with a newline. */
    if (length != 0) {
        fwrite(buffer, 1, length, stdout);
    }
    if (saw_newline) {
        putchar('\n');
    }

    free(buffer);
    return 0;
}

