#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 128;
    size_t len = 0;
    char *line = malloc(cap);
    if (line == NULL) {
        return 1;
    }

    /* Read one line (until newline or EOF), growing the buffer as needed. */
    int c;
    while ((c = getchar()) != EOF && c != '\n') {
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            char *tmp = realloc(line, new_cap);
            if (tmp == NULL) {
                free(line);
                return 1;
            }
            line = tmp;
            cap = new_cap;
        }
        line[len++] = (char)c;
    }
    line[len] = '\0';

    /* Compare from both ends, skipping spaces. */
    size_t left = 0;
    size_t right = len;
    int is_palindrome = 1;

    while (left < right) {
        while (left < right && line[left] == ' ') {
            left++;
        }
        while (left < right && line[right - 1] == ' ') {
            right--;
        }
        if (left >= right) {
            break;
        }
        if (line[left] != line[right - 1]) {
            is_palindrome = 0;
            break;
        }
        left++;
        right--;
    }

    printf("%d\n", is_palindrome);
    free(line);
    return 0;
}

#include <stdio.h>

int main(void) {
    int c;
    size_t count = 0;

    /* getchar returns int so EOF can be distinguished from valid bytes. */
    /* Stop at the first newline, so only the first line is processed. */
    while ((c = getchar()) != '\n' && c != EOF) {
        /* Manual case-insensitive checks avoid ctype.h signed-char pitfalls. */
        if (c == 'a' || c == 'A' ||
            c == 'e' || c == 'E' ||
            c == 'i' || c == 'I' ||
            c == 'o' || c == 'O' ||
            c == 'u' || c == 'U') {
            ++count;
        }
    }

    printf("%zu\n", count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char *line = NULL;
    size_t capacity = 0;

    /* getline handles arbitrary-length lines and keeps the trailing newline. */
    ssize_t length = getline(&line, &capacity, stdin);
    if (length < 0) {
        free(line);
        return 0;
    }

    for (ssize_t i = 0; i < length; i++) {
        unsigned char c = (unsigned char)line[i];
        if (c >= 'a' && c <= 'y') {
            line[i] = (char)(c + 1);
        } else if (c == 'z') {
            line[i] = 'a';
        }
    }

    /* fwrite preserves embedded NULs and does not add an extra newline. */
    fwrite(line, 1, (size_t)length, stdout);
    free(line);
    return 0;
}

#include <stdio.h>

int main(void) {
    int count = 0;
    int in_word = 0;
    int c;

    /* Read one line: stop at newline or EOF. Only ASCII spaces separate words. */
    while ((c = getchar()) != EOF && c != '\n') {
        if (c == ' ') {
            in_word = 0;
        } else if (!in_word) {
            /* Transition from separator (or start) to non-space begins a word. */
            ++count;
            in_word = 1;
        }
    }

    printf("%d\n", count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Read one arbitrarily long line from stdin using only standard C. */
static char *read_one_line(void)
{
    size_t cap = 0;
    size_t len = 0;
    char *buf = NULL;
    int c;

    while ((c = fgetc(stdin)) != EOF && c != '\n') {
        /* Make room for this character and a future terminating NUL. */
        if (len + 1 > cap) {
            size_t new_cap = cap ? cap * 2 : 64;
            while (new_cap < len + 2)
                new_cap *= 2;

            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                return NULL;
            }
            buf = tmp;
            cap = new_cap;
        }
        buf[len++] = (char)c;
    }

    /* Handle an empty line or immediate EOF. */
    if (buf == NULL) {
        buf = malloc(1);
        if (buf == NULL)
            return NULL;
        cap = 1;
        len = 0;
    } else if (len + 1 > cap) {
        char *tmp = realloc(buf, len + 1);
        if (tmp == NULL) {
            free(buf);
            return NULL;
        }
        buf = tmp;
    }

    buf[len] = '\0';
    return buf;
}

int main(void)
{
    char *line = read_one_line();
    if (line == NULL) {
        /* Still emit a newline for empty/failed input. */
        fputc('\n', stdout);
        return 0;
    }

    const char *delimiters = " \t\r\n\v\f";
    char *best_word = NULL;
    size_t best_length = 0;

    /* strtok treats runs of whitespace as one separator. */
    for (char *word = strtok(line, delimiters);
         word != NULL;
         word = strtok(NULL, delimiters)) {
        size_t word_length = strlen(word);

        /* Using > keeps the first word in case of a tie. */
        if (word_length > best_length) {
            best_length = word_length;
            best_word = word;
        }
    }

    if (best_word != NULL)
        fputs(best_word, stdout);
    fputc('\n', stdout);

    free(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t capacity = 1024;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return EXIT_FAILURE;
    }

    /* Read the entire stdin stream into a dynamically grown buffer. */
    int ch;
    while ((ch = fgetc(stdin)) != EOF) {
        if (length + 1 > capacity) {
            size_t new_capacity = capacity * 2;
            if (new_capacity < capacity) {
                free(buffer);
                return EXIT_FAILURE;
            }

            char *tmp = realloc(buffer, new_capacity);
            if (tmp == NULL) {
                free(buffer);
                return EXIT_FAILURE;
            }

            buffer = tmp;
            capacity = new_capacity;
        }

        buffer[length++] = (char)ch;
    }

    if (ferror(stdin)) {
        free(buffer);
        return EXIT_FAILURE;
    }

    /* Compact the buffer in place: skip spaces, keep every other byte. */
    char *src = buffer;
    const char *end = buffer + length;
    char *dst = buffer;

    while (src < end) {
        if (*src != ' ') {
            *dst++ = *src;
        }
        ++src;
    }

    *dst = '\0';

    /* Write exactly the compacted bytes; do not add or remove a newline. */
    size_t output_length = (size_t)(dst - buffer);
    if (fwrite(buffer, 1, output_length, stdout) != output_length) {
        free(buffer);
        return EXIT_FAILURE;
    }

    free(buffer);
    return EXIT_SUCCESS;
}

