#define BASE 1000000000U

/* Read all of stdin into a NUL-terminated buffer. */
static char *read_all(size_t *len_out) {
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    if (!buf) return NULL;

    for (;;) {
        if (len == cap) {
            if (cap > SIZE_MAX / 2) { free(buf); return NULL; }
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) { free(buf); return NULL; }
            buf = tmp;
        }
        size_t got = fread(buf + len, 1, cap - len, stdin);
        if (got == 0) break;
        len += got;
    }
    if (ferror(stdin)) { free(buf); return NULL; }

    if (len + 1 > cap) {
        char *tmp = realloc(buf, len + 1);
        if (!tmp) { free(buf); return NULL; }
        buf = tmp;
    }
    buf[len] = '\0';
    *len_out = len;
    return buf;
}

static int ensure_cap(uint32_t **d, size_t *cap, size_t need) {
    if (need <= *cap) return 1;
    size_t newcap = *cap ? *cap : 8;
    while (newcap < need) {
        if (newcap > SIZE_MAX / 2) return 0;
        newcap *= 2;
    }
    uint32_t *tmp = realloc(*d, newcap * sizeof(uint32_t));
    if (!tmp) return 0;
    for (size_t i = *cap; i < newcap; i++) tmp[i] = 0;
    *d = tmp;
    *cap = newcap;
    return 1;
}

int main(void) {
    size_t total_len = 0;
    char *input = read_all(&total_len);
    if (!input) return 1;

    /* Base-1e9 little-endian big integer, starting at zero. */
    size_t cap = 8, n = 1;
    uint32_t *d = calloc(cap, sizeof(uint32_t));
    if (!d) { free(input); return 1; }

    /* Process only the first input line. */
    for (size_t i = 0; i < total_len; i++) {
        char c = input[i];
        if (c == '\n') break;

        int val;
        if (c >= '0' && c <= '9') val = c - '0';
        else if (c >= 'a' && c <= 'f') val = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') val = c - 'A' + 10;
        else continue; /* skip spaces, \r, 0x prefix letters, etc. */

        /* result = result * 16 */
        uint64_t carry = 0;
        for (size_t j = 0; j < n; j++) {
            uint64_t t = (uint64_t)d[j] * 16 + carry;
            d[j] = (uint32_t)(t % BASE);
            carry = t / BASE;
        }
        while (carry) {
            if (!ensure_cap(&d, &cap, n + 1)) { free(d); free(input); return 1; }
            d[n] = 0;
            uint64_t t = (uint64_t)d[n] + carry;
            d[n] = (uint32_t)(t % BASE);
            carry = t / BASE;
            n++;
        }

        /* result += digit */
        uint64_t t = (uint64_t)d[0] + (uint64_t)val;
        d[0] = (uint32_t)(t % BASE);
        carry = t / BASE;
        size_t j = 1;
        while (carry) {
            if (j >= n) {
                if (!ensure_cap(&d, &cap, n + 1)) { free(d); free(input); return 1; }
                d[n] = 0;
                n++;
            }
            uint64_t t2 = (uint64_t)d[j] + carry;
            d[j] = (uint32_t)(t2 % BASE);
            carry = t2 / BASE;
            j++;
        }
    }

    /* Trim leading zero limbs. */
    while (n > 1 && d[n - 1] == 0) n--;

    /* Print decimal value. */
    printf("%u", (unsigned)d[n - 1]);
    for (size_t t = 0; t + 1 < n; t++) {
        size_t idx = n - 2 - t;
        printf("%09u", (unsigned)d[idx]);
    }
    putchar('\n');

    free(d);
    free(input);
    return 0;
}

