/* Read one line from stdin, growing the buffer as needed. */
static char *read_line(void)
{
    size_t cap = 128;
    size_t len = 0;
    char *buf = malloc(cap);

    if (buf == NULL) {
        return NULL;
    }

    for (;;) {
        int ch = fgetc(stdin);

        if (ch == EOF) {
            break;
        }

        /* Need room for this character plus the final '\0'. */
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (tmp == NULL) {
                free(buf);
                return NULL;
            }
            buf = tmp;
        }

        buf[len++] = (char)ch;

        if (ch == '\n') {
            break;
        }
    }

    buf[len] = '\0';
    return buf;
}

int main(void)
{
    char *line = read_line();

    if (line == NULL) {
        return 1;
    }

    /* Convert ASCII lowercase letters to uppercase by subtracting
       the fixed offset between 'a' and 'A' (32). */
    for (size_t i = 0; line[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)line[i];

        if (c >= 'a' && c <= 'z') {
            line[i] = (char)(c - ('a' - 'A'));
        }
    }

    fputs(line, stdout);
    free(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    /* Read all of stdin into a dynamically growing buffer. */
    size_t cap = 0;
    size_t len = 0;
    char *buf = NULL;
    char chunk[8192];
    size_t r;
    int failed = 0;

    while (!failed && (r = fread(chunk, 1, sizeof chunk, stdin)) > 0) {
        size_t need = len + r;

        if (need < len) { /* overflow guard */
            failed = 1;
            break;
        }

        if (cap < need) {
            size_t newcap = cap ? cap * 2 : (size_t)8192;
            if (newcap < cap) newcap = (size_t)-1;

            while (newcap < need) {
                if (newcap == (size_t)-1) break;
                size_t next = newcap * 2;
                if (next < newcap) next = (size_t)-1;
                newcap = next;
            }

            if (newcap < need) {
                failed = 1;
                break;
            }

            char *tmp = realloc(buf, newcap);
            if (tmp == NULL) {
                failed = 1;
                break;
            }
            buf = tmp;
            cap = newcap;
        }

        /* Copy this chunk after the bytes already stored. */
        for (size_t i = 0; i < r; ++i) {
            buf[len + i] = chunk[i];
        }
        len += r;
    }

    if (ferror(stdin)) {
        failed = 1;
    }

    int only_digits = 0;

    if (!failed) {
        /* A trailing newline terminates the line but is not part of it. */
        if (len > 0 && buf[len - 1] == '\n') {
            --len;
        }

        only_digits = 1;
        for (size_t i = 0; i < len; ++i) {
            if (buf[i] < '0' || buf[i] > '9') {
                only_digits = 0;
                break;
            }
        }
    }

    printf("%d\n", only_digits);
    free(buf);
    return 0;
}

