int main(void)
{
    int n;

    /* Read the count first; reject invalid or negative counts. */
    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    int *values = NULL;
    if (n > 0) {
        /* Allocate using size_t arithmetic to avoid signed overflow. */
        values = malloc((size_t)n * sizeof *values);
        if (values == NULL) {
            return 1;
        }

        for (int i = 0; i < n; ++i) {
            if (scanf("%d", &values[i]) != 1) {
                free(values);
                return 1;
            }
        }
    }

    /* Ascending bubble sort with an early exit when no swaps occur. */
    for (int i = 0; i < n - 1; ++i) {
        int swapped = 0;
        for (int j = 0; j < n - 1 - i; ++j) {
            if (values[j] > values[j + 1]) {
                int temporary = values[j];
                values[j] = values[j + 1];
                values[j + 1] = temporary;
                swapped = 1;
            }
        }
        if (!swapped) {
            break;
        }
    }

    /* Print values separated by single spaces, with a final newline. */
    for (int i = 0; i < n; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        printf("%d", values[i]);
    }
    if (n > 0) {
        putchar('\n');
    }

    free(values);
    return 0;
}

