/* Recursive quicksort using a middle-element pivot. */
static void quicksort(int *a, int left, int right)
{
    if (left >= right) {
        return; /* Base case: 0 or 1 element. */
    }

    /* Middle pivot avoids the worst case on already-sorted input. */
    int pivot = a[left + (right - left) / 2];
    int i = left;
    int j = right;

    while (i <= j) {
        while (a[i] < pivot) {
            ++i;
        }
        while (a[j] > pivot) {
            --j;
        }
        if (i <= j) {
            int tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
            ++i;
            --j;
        }
    }

    /* Recurse on the two partitions; i and j have crossed. */
    if (left < j) {
        quicksort(a, left, j);
    }
    if (i < right) {
        quicksort(a, i, right);
    }
}

