        if (scanf("%d", &a[i]) != 1) {
            free(a);
            return 1;
        }
    }

    if (n > 1) {
        quicksort(a, 0, n - 1);
    }

    for (int i = 0; i < n; ++i) {
        printf("%d", a[i]);
        if (i + 1 < n) {
            putchar(' ');
        }
    }
