/* Merge two sorted halves [lo, mid) and [mid, hi) using tmp as scratch space. */
static void merge(int *a, int *tmp, size_t lo, size_t mid, size_t hi)
{
    size_t i = lo, j = mid, k = lo;

    while (i < mid && j < hi) {
        if (a[i] <= a[j])
            tmp[k++] = a[i++];
        else
            tmp[k++] = a[j++];
    }
    while (i < mid)
        tmp[k++] = a[i++];
    while (j < hi)
        tmp[k++] = a[j++];

    /* Copy the merged range back into the original array. */
    for (i = lo; i < hi; i++)
        a[i] = tmp[i];
}

/* Sort a[lo..hi) recursively, reusing the same helper array. */
static void merge_sort(int *a, int *tmp, size_t lo, size_t hi)
{
    if (hi - lo < 2)
        return;

    /* Avoid overflow when computing the midpoint. */
    size_t mid = lo + (hi - lo) / 2;
    merge_sort(a, tmp, lo, mid);
    merge_sort(a, tmp, mid, hi);
    merge(a, tmp, lo, mid, hi);
}

