            }
        }

        merge_sort(a, tmp, 0, n);
    }

    for (size_t i = 0; i < n; i++) {
        if (i != 0)
            putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');

    free(a);
    free(tmp);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* Restore the max-heap property for the subtree rooted at i.
   heap_size is the number of elements currently in the heap. */
static void sift_down(int *heap, size_t heap_size, size_t i)
{
    while (2 * i + 1 < heap_size) {
        size_t largest = 2 * i + 1;          /* left child */
        size_t right = largest + 1;          /* right child */

        if (right < heap_size && heap[right] > heap[largest])
            largest = right;

        /* If the parent is already largest, the heap property holds. */
        if (heap[largest] <= heap[i])
            break;

        /* Otherwise swap parent with largest child and continue downward. */
        int tmp = heap[i];
        heap[i] = heap[largest];
        heap[largest] = tmp;
        i = largest;
    }
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0)
        return 1;

    if (n == 0) {
        putchar('\n');
        return 0;
    }

    int *a = malloc((size_t)n * sizeof *a);
    if (a == NULL)
        return 1;

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            free(a);
            return 1;
        }
    }

    /* Build a max-heap. The last parent is at index n/2 - 1,
       so start from n/2 and decrement before each call. */
    for (size_t i = (size_t)n / 2; i-- > 0; )
        sift_down(a, (size_t)n, i);

    /* Repeatedly move the current maximum to the end and shrink the heap. */
    for (size_t end = (size_t)n; end > 1; end--) {
        int tmp = a[0];
        a[0] = a[end - 1];
        a[end - 1] = tmp;
        sift_down(a, end - 1, 0);
    }

    for (int i = 0; i < n; i++)
        printf("%d%c", a[i], i + 1 < n ? ' ' : '\n');

    free(a);
    return 0;
}

