        }
    }

    long long k;
    if (scanf("%lld", &k) != 1) {
        free(a);
        return 0;
    }

    if (N == 0) {
        putchar('\n');
        free(a);
        return 0;
    }

    /* Normalize k into [0, N), including negative inputs. */
    long long kk = k % (long long)N;
    if (kk < 0) {
        kk += (long long)N;
    }

    /* A right rotation by kk moves the last kk elements to the front. */
    for (size_t i = 0; i < N; ++i) {
        size_t idx = (i < (size_t)kk)
                         ? N - (size_t)kk + i
                         : i - (size_t)kk;
        if (i) {
            putchar(' ');
        }
        printf("%lld", a[idx]);
    }
    putchar('\n');

    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;

    /* Read the number of elements; reject malformed or negative input. */
    if (scanf("%d", &n) != 1 || n < 0) {
        return 1;
    }

    /* Allocate storage for the sorted input. */
    int *a = NULL;
    if (n > 0) {
        a = malloc((size_t)n * sizeof *a);
        if (a == NULL) {
            return 1;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            free(a);
            return 1;
        }
    }

    /* Two-pointer deduplication in place:
       'unique' is the write position; a[unique-1] is the last kept value. */
    int unique = 0;
    for (int i = 0; i < n; ++i) {
        if (unique == 0 || a[i] != a[unique - 1]) {
            a[unique++] = a[i];
        }
    }

    /* Print only the deduplicated prefix. */
    for (int i = 0; i < unique; ++i) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", a[i]);
    }
    putchar('\n');

    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n, m;

    /* Read matrix dimensions first. */
    if (scanf("%d %d", &n, &m) != 2) {
        return 0;
    }
    if (n < 0 || m < 0) {
        return 1;
    }

    /* An empty matrix has no entries to transpose. */
    if (n == 0 || m == 0) {
        return 0;
    }

    /* Store the matrix in one flat array in row-major order:
       element (i, j) is at index i * m + j. */
    size_t total = (size_t)n * (size_t)m;
    int *matrix = malloc(total * sizeof *matrix);
    if (matrix == NULL) {
        return 1;
    }

    for (size_t k = 0; k < total; ++k) {
        if (scanf("%d", &matrix[k]) != 1) {
            free(matrix);
            return 1;
        }
    }

    /* The transpose has m rows and n columns. Swapping the loop order
       visits original column j as the new row j. */
    for (int j = 0; j < m; ++j) {
        for (int i = 0; i < n; ++i) {
            if (i > 0) {
                putchar(' ');
            }
            printf("%d", matrix[(size_t)i * m + j]);
        }
        putchar('\n');
    }

    free(matrix);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a[3][3], b[3][3], c[3][3];

    /* Read the first matrix, row by row. */
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            scanf("%d", &a[i][j]);

    /* Read the second matrix. */
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            scanf("%d", &b[i][j]);

    /* Compute C = A * B. c[i][k] accumulates a[i][j] * b[j][k]. */
    for (int i = 0; i < 3; i++) {
        for (int k = 0; k < 3; k++) {
            int sum = 0;
            for (int j = 0; j < 3; j++)
                sum += a[i][j] * b[j][k];
            c[i][k] = sum;
        }
    }

    /* Print the product matrix. */
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++)
            printf("%d%c", c[i][j], j == 2 ? '\n' : ' ');
    }

    return 0;
}

#include <stdio.h>
