static int cmp_ll(const void *x, const void *y)
{
    const long long *a = x;
    const long long *b = y;
    /* Avoid subtraction to prevent overflow. */
    if (*a < *b) return -1;
    if (*a > *b) return 1;
    return 0;
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n <= 0) {
        return 0;
    }

    long long *values = malloc((size_t)n * sizeof *values);
    if (values == NULL) {
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%lld", &values[i]) != 1) {
            free(values);
            return 1;
        }
    }

    qsort(values, (size_t)n, sizeof *values, cmp_ll);

    /* Lower median: for even n this is the element just below the middle. */
    printf("%lld\n", values[(n - 1) / 2]);

    free(values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;

    /* Read the count first. */
    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    /* Allocate storage for the n values. */
    long long *a = (n == 0) ? NULL : malloc((size_t)n * sizeof *a);
    if (n > 0 && a == NULL) {
        return 1;
    }

    /* Read all values. */
    for (int i = 0; i < n; ++i) {
        if (scanf("%lld", &a[i]) != 1) {
            free(a);
            return 1;
        }
    }

    /* O(n^2) inversion count: pairs (i, j) with i < j and a[i] > a[j]. */
    long long inversions = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (a[i] > a[j]) {
                ++inversions;
            }
        }
    }

    printf("%lld\n", inversions);
    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    /* Use a dynamic array so very large inputs do not rely on VLAs. */
    long long *values = NULL;
    if (n > 0) {
        values = malloc((size_t)n * sizeof *values);
        if (values == NULL) {
            return 1;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%lld", &values[i]) != 1) {
            free(values);
            return 1;
        }
    }

    /* Sorting groups equal values together, making counting simple. */
    qsort(values, (size_t)n, sizeof *values, cmp_ll);

    /* Print each distinct value followed by its run length. */
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && values[j] == values[i]) {
            ++j;
        }
        printf("%lld %d\n", values[i], j - i);
        i = j;
    }

    free(values);
    return 0;
}

#include <stdio.h>

int main(void) {
    char grid[10][10];
    int n = 0;
    int c;

    /* Read exactly 100 grid characters, ignoring any other whitespace. */
    while (n < 100 && (c = getchar()) != EOF) {
        if (c == '.' || c == '#') {
            grid[n / 10][n % 10] = (char)c;
            ++n;
        }
    }

    int visited[10][10] = {0};
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};
    int regions = 0;

    for (int r = 0; r < 10; ++r) {
        for (int col = 0; col < 10; ++col) {
            if (grid[r][col] == '#' && !visited[r][col]) {
                ++regions;

                /* Iterative DFS using a small stack. */
                int stack[100][2];
                int sp = 0;
                stack[sp][0] = r;
                stack[sp][1] = col;
                ++sp;
                visited[r][col] = 1;

                while (sp > 0) {
                    --sp;
                    int cr = stack[sp][0];
                    int cc = stack[sp][1];

                    for (int d = 0; d < 4; ++d) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < 10 && nc >= 0 && nc < 10 &&
                            !visited[nr][nc] && grid[nr][nc] == '#') {
                            visited[nr][nc] = 1;
                            stack[sp][0] = nr;
                            stack[sp][1] = nc;
                            ++sp;
                        }
                    }
                }
            }
        }
    }

    printf("%d\n", regions);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("0\n");
        return 0;
    }

    int *a = malloc((size_t)n * sizeof *a);
    int *dp = malloc((size_t)n * sizeof *dp);
    if (!a || !dp) {
        free(a);
        free(dp);
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            free(a);
            free(dp);
            return 1;
        }
    }

    int best = 0;
    for (int i = 0; i < n; ++i) {
        /* Every element forms a subsequence of length 1 by itself. */
        dp[i] = 1;
        for (int j = 0; j < i; ++j) {
            /* Strictly increasing means a[j] must be less than a[i]. */
            if (a[j] < a[i] && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
            }
        }
        if (dp[i] > best) {
            best = dp[i];
        }
    }

    printf("%d\n", best);
    free(a);
    free(dp);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) {
        return 0;
    }

    long long x;
    if (scanf("%lld", &x) != 1) {
        return 0;
    }

    /* Start Kadane's with the first element so all-negative arrays work. */
    long long max_ending = x;
    long long max_so_far = x;

    for (int i = 1; i < n; i++) {
        if (scanf("%lld", &x) != 1) {
            break;
        }
        /* Either start a new subarray at x or extend the previous one. */
        max_ending = (x > max_ending + x) ? x : max_ending + x;
        if (max_ending > max_so_far) {
            max_so_far = max_ending;
        }
    }

    printf("%lld\n", max_so_far);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int cmp_weights(const void *a, const void *b)
{
    const long long *x = a;
    const long long *y = b;

    if (*x < *y) return -1;
    if (*x > *y) return 1;
    return 0;
}

int main(void)
{
    int n;
    long long capacity;

    /* Read n and capacity; scanf handles whitespace/newlines. */
    if (scanf("%d %lld", &n, &capacity) != 2) {
        return 0;
    }

    if (n < 0) {
        n = 0;
    }

    long long *weights = NULL;
    if (n > 0) {
        weights = malloc((size_t)n * sizeof(*weights));
        if (weights == NULL) {
            return 1;
        }

        for (int i = 0; i < n; ++i) {
            if (scanf("%lld", &weights[i]) != 1) {
                free(weights);
                return 1;
            }
        }
    }

    /* Smallest weights first maximizes the count of items. */
    qsort(weights, (size_t)n, sizeof(*weights), cmp_weights);

    long long used = 0;
    int count = 0;

    for (int i = 0; i < n; ++i) {
        /*
         * Since weights are sorted increasingly, once one item does not fit,
         * no later item can fit either. This also works for non-positive
         * weights because they are considered first.
         */
        if (used + weights[i] <= capacity) {
            used += weights[i];
            ++count;
        } else {
            break;
        }
    }

    printf("%d\n", count);
    free(weights);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

int main(void) {
    int n;

    /* Read the element count; reject invalid or negative counts. */
    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    /* Start with a small malloc'd buffer and grow it by doubling. */
    size_t count = 0;
    size_t cap = 1;
    int *arr = malloc(cap * sizeof *arr);
    if (arr == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        int value;
        if (scanf("%d", &value) != 1) {
            free(arr);
            return 1;
        }

        /* Double capacity before inserting when the buffer is full. */
        if (count == cap) {
            /* Avoid size_t overflow while doubling. */
            if (cap > (SIZE_MAX / sizeof *arr) / 2) {
                free(arr);
                return 1;
            }
            cap *= 2;

            int *tmp = realloc(arr, cap * sizeof *arr);
            if (tmp == NULL) {
                free(arr);
                return 1;
            }
            arr = tmp;
        }

        arr[count++] = value;
    }

    /* Sum can exceed int range, so accumulate in long long. */
    long long sum = 0;
    for (size_t i = 0; i < count; i++) {
        sum += arr[i];
    }

    printf("%lld\n", sum);
    free(arr);
    return 0;
}

