#include <stdio.h>
#include <stdlib.h>

struct Complex {
    double re;
    double im;
};

static struct Complex multiply(struct Complex a, struct Complex b)
{
    struct Complex result;
    /* (a+bi)(c+di) = (ac-bd) + (ad+bc)i */
    result.re = a.re * b.re - a.im * b.im;
    result.im = a.re * b.im + a.im * b.re;
    return result;
}

int main(void)
{
    /* Read the whole input so formats like "1+2i 3+4i" and "1 2 3 4" both work. */
    size_t cap = 1, len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        return 1;
    }

    int ch;
    while ((ch = fgetc(stdin)) != EOF) {
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                return 1;
            }
            buf = tmp;
            cap = new_cap;
        }
        buf[len++] = (char)ch;
    }
    buf[len] = '\0';

    /* Extract the first four numeric values, skipping letters such as i. */
    double values[4] = {0.0, 0.0, 0.0, 0.0};
    int count = 0;
    char *p = buf;
    while (*p != '\0' && count < 4) {
        char *end = NULL;
        double x = strtod(p, &end);
        if (end != p) {
            values[count++] = x;
            p = end;
        } else {
            ++p; /* Skip a non-numeric character. */
        }
    }

    free(buf);

    struct Complex a = {values[0], values[1]};
    struct Complex b = {values[2], values[3]};
    struct Complex product = multiply(a, b);

    printf("%.6f %.6f\n", product.re, product.im);
    return 0;
}

