#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

int main(void) {
    int n;

    /* First value is the number of integers to read. */
    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    Node *head = NULL;
    Node *tail = NULL;

    /* Build the singly linked list in input order. */
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            break;
        }

        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            perror("malloc");
            return 1;
        }
        node->value = x;
        node->next = NULL;

        if (tail == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    /* Explicit stack array: stores node pointers, no recursion. */
    Node **stack = (n > 0) ? malloc((size_t)n * sizeof *stack) : NULL;
    if (n > 0 && stack == NULL) {
        perror("malloc");
        return 1;
    }

    int top = 0;
    for (Node *cur = head; cur != NULL; cur = cur->next) {
        stack[top++] = cur;  /* push */
    }

    /* Pop and print to produce reversed order. */
    int first = 1;
    while (top > 0) {
        Node *node = stack[--top];  /* pop */
        if (!first) {
            putchar(' ');
        }
        first = 0;
        printf("%d", node->value);
    }
    putchar('\n');

    free(stack);

    /* Free the linked list. */
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        free(cur);
        cur = next;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* Reverse the list in place by relinking pointers.
   Save the old next pointer before overwriting it. */
static Node *reverse_list(Node *head)
{
    Node *previous = NULL;

    while (head != NULL) {
        Node *next = head->next;   /* preserve rest of list */
        head->next = previous;     /* relink current node */
        previous = head;           /* advance previous */
        head = next;               /* advance current */
    }

    return previous;
}

static void free_list(Node *head)
{
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    Node *head = NULL;
    Node *tail = NULL;

    for (int i = 0; i < n; ++i) {
        int value;

        if (scanf("%d", &value) != 1) {
            break;
        }

        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            free_list(head);
            return 1;
        }

        node->value = value;
        node->next = NULL;

        /* Keep a tail pointer so appending stays O(1). */
        if (tail == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    head = reverse_list(head);

    for (Node *p = head; p != NULL; p = p->next) {
        printf("%d", p->value);
        if (p->next != NULL) {
            putchar(' ');
        }
    }
    putchar('\n');

    free_list(head);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

static Node *new_node(int value)
{
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static void insert_bst(Node **root, int value)
{
    Node **link = root;
    /* Walk down to the insertion point, keeping BST order. */
    while (*link != NULL) {
        if (value <= (*link)->value) {
            link = &(*link)->left;
        } else {
            link = &(*link)->right;
        }
    }
    *link = new_node(value);
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    Node *root = NULL;
    for (int i = 0; i < n; ++i) {
        int value;
        if (scanf("%d", &value) != 1) {
            return 0;
        }
        insert_bst(&root, value);
    }

    /* An explicit stack is enough: a BST with n nodes has depth at most n. */
    size_t capacity = n > 0 ? (size_t)n : 1;
    Node **stack = malloc(capacity * sizeof *stack);
    if (stack == NULL) {
        fprintf(stderr, "out of memory\n");
        return EXIT_FAILURE;
    }

    Node *current = root;
    size_t top = 0;
    int first = 1;

    /* Push the left spine, then pop, print, and descend to the right. */
    while (current != NULL || top > 0) {
        while (current != NULL) {
            stack[top++] = current;
            current = current->left;
        }
        current = stack[--top];
        if (first) {
            first = 0;
        } else {
            putchar(' ');
        }
        printf("%d", current->value);
        current = current->right;
    }

    putchar('\n');
    free(stack);
    return 0;
}

#include <stdio.h>

#define STACK_CAPACITY 100

int main(void) {
    int stack[STACK_CAPACITY];
    int top = -1; /* -1 means empty; otherwise index of top element */
    char command;

    /* Leading space in " %c" skips all whitespace before the command letter. */
    while (scanf(" %c", &command) == 1) {
        if (command == 'p') {
            int value;

            if (scanf("%d", &value) != 1) {
                break; /* Malformed push command */
            }
            if (top + 1 < STACK_CAPACITY) {
                stack[++top] = value;
            }
            /* Full stack: extra pushes are ignored. */
        } else if (command == 'o') {
            if (top >= 0) {
                printf("%d\n", stack[top--]);
            }
            /* Empty stack: pops are ignored. */
        } else if (command == 'q') {
            break;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define QUEUE_CAPACITY 100

typedef struct {
    int data[QUEUE_CAPACITY];
    int head;   /* index of the next element to remove */
    int tail;   /* index where the next element will be stored */
    int count;  /* number of elements currently stored */
} IntQueue;

static void queue_init(IntQueue *q) {
    q->head = 0;
    q->tail = 0;
    q->count = 0;
}

/* Returns 0 when the queue is full. */
static int queue_enqueue(IntQueue *q, int value) {
    if (q->count == QUEUE_CAPACITY) {
        return 0;
    }
    q->data[q->tail] = value;
    /* Wrap the tail around to the beginning of the array. */
    q->tail = (q->tail + 1) % QUEUE_CAPACITY;
    q->count++;
    return 1;
}

/* Returns 0 when the queue is empty. */
static int queue_dequeue(IntQueue *q, int *value) {
    if (q->count == 0) {
        return 0;
    }
    *value = q->data[q->head];
    /* Wrap the head around to the beginning of the array. */
    q->head = (q->head + 1) % QUEUE_CAPACITY;
    q->count--;
    return 1;
}

int main(void) {
    IntQueue queue;
    queue_init(&queue);

    for (;;) {
        char command;

        /* The leading space skips whitespace, including newlines. */
        if (scanf(" %c", &command) != 1) {
            break;
        }

        if (command == 'e') {
            int value;
            if (scanf("%d", &value) != 1) {
                fprintf(stderr, "missing enqueue value\n");
                return EXIT_FAILURE;
            }
            if (!queue_enqueue(&queue, value)) {
                fprintf(stderr, "queue full\n");
            }
        } else if (command == 'd') {
            int value;
            if (queue_dequeue(&queue, &value)) {
                printf("%d\n", value);
            } else {
                fprintf(stderr, "queue empty\n");
            }
        } else if (command == 'q') {
            break;
        } else {
            fprintf(stderr, "unknown command: %c\n", command);
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    char value;
    struct Node *next;
} Node;

int main(void) {
    Node *head = NULL;
    Node *tail = NULL;
    int c;

    /* Read one line. Keeping '\n' makes "print it back" exact. */
    while ((c = getchar()) != EOF) {
        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            /* Free nodes already created before failing. */
            while (head != NULL) {
                Node *tmp = head;
                head = head->next;
                free(tmp);
            }
            return 1;
        }

        node->value = (char)c;
        node->next = NULL;

        /* Append at tail so character order is preserved. */
        if (tail != NULL) {
            tail->next = node;
        } else {
            head = node;
        }
        tail = node;

        if (c == '\n') {
            break;
        }
    }

    /* Print every stored character, including a final newline if present. */
    for (Node *p = head; p != NULL; p = p->next) {
        putchar(p->value);
    }

    /* Free every node in the list. */
    while (head != NULL) {
        Node *tmp = head;
        head = head->next;
        free(tmp);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define STACK_CAPACITY 256

int main(void)
{
    int stack[STACK_CAPACITY];
    size_t sp = 0; /* stack pointer / current size */

    int c;
    /* Read only the first input line, character by character. */
    while ((c = getchar()) != '\n' && c != EOF) {
        if (c == ' ' || c == '\t' || c == '\r') {
            continue; /* ignore whitespace */
        }

        if (c >= '0' && c <= '9') {
            if (sp == STACK_CAPACITY) {
                fprintf(stderr, "stack overflow\n");
                return EXIT_FAILURE;
            }
            stack[sp++] = c - '0';
        } else if (c == '+' || c == '-' || c == '*' || c == '/') {
            if (sp < 2) {
                fprintf(stderr, "stack underflow\n");
                return EXIT_FAILURE;
            }
            /* Pop right operand first, then left operand. */
            int right = stack[--sp];
            int left = stack[--sp];
            int result;

            switch (c) {
                case '+': result = left + right; break;
                case '-': result = left - right; break;
                case '*': result = left * right; break;
                case '/':
                    if (right == 0) {
                        fprintf(stderr, "division by zero\n");
                        return EXIT_FAILURE;
                    }
                    result = left / right; /* C11 integer division */
                    break;
                default:
                    fprintf(stderr, "invalid operator\n");
                    return EXIT_FAILURE;
            }

            if (sp == STACK_CAPACITY) {
                fprintf(stderr, "stack overflow\n");
                return EXIT_FAILURE;
            }
            stack[sp++] = result;
        } else {
            fprintf(stderr, "invalid character: %c\n", c);
            return EXIT_FAILURE;
        }
    }

    if (sp != 1) {
        fprintf(stderr, "invalid expression\n");
        return EXIT_FAILURE;
    }

    printf("%d\n", stack[0]);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

/* Parse one signed integer manually; no strtol. Returns 1 on success. */
static int parse_number(const char **p, long long *value)
{
    while (isspace((unsigned char)**p))
        (*p)++;

    int sign = 1;
    if (**p == '+' || **p == '-') {
        if (**p == '-')
            sign = -1;
        (*p)++;
    }

    if (!isdigit((unsigned char)**p))
        return 0;

    long long v = 0;
    while (isdigit((unsigned char)**p)) {
        /* Accumulate digits by shifting the previous value left in base 10. */
        v = v * 10 + (**p - '0');
        (*p)++;
    }

    *value = sign * v;
    return 1;
}

int main(void)
{
    /* Read all of stdin into a dynamically grown buffer. */
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        perror("malloc");
        return 1;
    }

    for (;;) {
        if (len == cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (tmp == NULL) {
                perror("realloc");
                free(buf);
                return 1;
            }
            buf = tmp;
        }
        size_t got = fread(buf + len, 1, cap - len, stdin);
        len += got;
        if (got == 0)
            break;
    }
    buf[len] = '\0';

    const char *p = buf;
    long long total = 0;
    long long term;

    if (!parse_number(&p, &term)) {
        fprintf(stderr, "invalid expression\n");
        free(buf);
        return 1;
    }
    total = term;

    /* Each '+' or '-' starts another signed term. */
    for (;;) {
        while (isspace((unsigned char)*p))
            p++;

        if (*p != '+' && *p != '-')
            break;

        char op = *p++;
        if (!parse_number(&p, &term)) {
            fprintf(stderr, "invalid expression\n");
            free(buf);
            return 1;
        }

        if (op == '-')
            total -= term;
        else
            total += term;
    }

    printf("%lld\n", total);
    free(buf);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
