/* Comparator for qsort on an array of char * values. */
static int compare_words(const void *left, const void *right)
{
    const char *const *a = left;
    const char *const *b = right;
    return strcmp(*a, *b);
}

/* Read all of stdin into one NUL-terminated, dynamically grown buffer. */
static char *read_all_stdin(void)
{
    size_t capacity = 4096;
    size_t length = 0;
    char *buffer = malloc(capacity);
    if (buffer == NULL) {
        return NULL;
    }

    int ch;
    while ((ch = fgetc(stdin)) != EOF) {
        if (length + 1 >= capacity) {
            /* Keep one byte free for the final NUL terminator. */
            capacity *= 2;
            char *grown = realloc(buffer, capacity);
            if (grown == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = grown;
        }
        buffer[length++] = (char)ch;
    }
    buffer[length] = '\0';
    return buffer;
}

int main(void)
{
    char *input = read_all_stdin();
    if (input == NULL) {
        return 1;
    }

    /* Tokenize in place: each word pointer points into input. */
    size_t word_count = 0;
    size_t word_capacity = 0;
    char **words = NULL;
    char *cursor = input;

    while (*cursor != '\0') {
        while (isspace((unsigned char)*cursor)) {
            ++cursor;
        }
        if (*cursor == '\0') {
            break;
        }

        if (word_count == word_capacity) {
            size_t new_capacity = word_capacity == 0 ? 16 : word_capacity * 2;
            char **grown = realloc(words, new_capacity * sizeof *grown);
            if (grown == NULL) {
                free(words);
                free(input);
                return 1;
            }
            words = grown;
            word_capacity = new_capacity;
        }

        words[word_count++] = cursor;

        while (*cursor != '\0' && !isspace((unsigned char)*cursor)) {
            ++cursor;
        }
        if (*cursor != '\0') {
            *cursor++ = '\0'; /* Terminate this word and advance. */
        }
    }

    qsort(words, word_count, sizeof *words, compare_words);

    for (size_t i = 0; i < word_count; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        fputs(words[i], stdout);
    }
    if (word_count != 0) {
        putchar('\n');
    }

    free(words);
    free(input);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static int roman_value(char c)
{
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return 0;
    }
}

int main(void)
{
    /* Read all of stdin into a dynamically grown buffer. */
    size_t cap = 256, len = 0;
    char *input = malloc(cap);
    if (input == NULL) {
        return 1;
    }

    int ch;
    while ((ch = fgetc(stdin)) != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(input, cap);
            if (tmp == NULL) {
                free(input);
                return 1;
            }
            input = tmp;
        }
        input[len++] = (char)ch;
    }
    input[len] = '\0';

    /* Keep only valid Roman letters, converting lowercase to uppercase. */
    char *roman = malloc(len + 1);
    if (roman == NULL) {
        free(input);
        return 1;
    }

    size_t r = 0;
    for (size_t i = 0; i < len; i++) {
        char c = input[i];
        if (isspace((unsigned char)c)) {
            continue;
        }
        if (c >= 'a' && c <= 'z') {
            c = (char)(c - 'a' + 'A');
        }
        if (roman_value(c) != 0) {
            roman[r++] = c;
        }
    }
    roman[r] = '\0';

    /* Subtract a value when it is smaller than the following value. */
    long total = 0;
    for (size_t i = 0; i < r; i++) {
        int current = roman_value(roman[i]);
        if (i + 1 < r && current < roman_value(roman[i + 1])) {
            total -= current;
        } else {
            total += current;
        }
    }

    printf("%ld\n", total);

    free(roman);
    free(input);
    return 0;
}

