int main(void) {
    int n;

    /* Read the single table size; fail cleanly on bad input. */
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    /* A multiplication table needs a nonnegative size. */
    if (n < 0) {
        return 1;
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            printf("%d", i * j);

            /* Print a separator only between values, not after the last one. */
            if (j < n) {
                putchar(' ');
            }
        }
        putchar('\n');
    }

    return 0;
}

#include <stdio.h>

int main(void) {
    int n;

    /* Read the row count; ignore any extra input. */
    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    for (int row = 0; row < n; ++row) {
        /* Indent so the triangle is centred. */
        for (int space = 0; space < n - row - 1; ++space) {
            putchar(' ');
        }

        unsigned long long value = 1ULL;
        for (int col = 0; col <= row; ++col) {
            if (col > 0) {
                putchar(' ');
            }
            printf("%llu", value);

            /* Update to the next binomial coefficient without factorials. */
            value = value * (unsigned long long)(row - col)
                  / (unsigned long long)(col + 1);
        }
        putchar('\n');
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n <= 0) {
        return 0;
    }

    /* Flat n*n matrix: row i, column j is at i * n + j. */
    int *a = calloc((size_t)n * n, sizeof *a);
    if (a == NULL) {
        return 1;
    }

    int top = 0, bottom = n - 1, left = 0, right = n - 1;
    int value = 1;

    /* Peel the matrix one layer at a time: right, down, left, up. */
    while (value <= n * n) {
        for (int c = left; c <= right && value <= n * n; c++) {
            a[top * n + c] = value++;
        }
        top++;

        for (int r = top; r <= bottom && value <= n * n; r++) {
            a[r * n + right] = value++;
        }
        right--;

        if (top <= bottom) {
            for (int c = right; c >= left && value <= n * n; c--) {
                a[bottom * n + c] = value++;
            }
            bottom--;
        }

        if (left <= right) {
            for (int r = bottom; r >= top && value <= n * n; r--) {
                a[r * n + left] = value++;
            }
            left++;
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j > 0) {
                putchar(' ');
            }
            printf("%d", a[i * n + j]);
        }
        putchar('\n');
    }

    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Count decimal digits in a run length. */
static size_t count_digits(size_t value)
{
    size_t digits = 0;
    do {
        ++digits;
        value /= 10;
    } while (value != 0);
    return digits;
}

/* Build the next look-and-say term from the current term. */
static char *next_term(const char *current)
{
    /* First calculate the exact output size, including multi-digit counts. */
    size_t total = 0;
    for (size_t i = 0; current[i] != '\0'; ) {
        size_t j = i;
        while (current[j] == current[i]) {
            ++j;
        }
        total += count_digits(j - i) + 1; /* count digits plus described digit */
        i = j;
    }

    char *next = malloc(total + 1);
    if (next == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    size_t pos = 0;
    for (size_t i = 0; current[i] != '\0'; ) {
        size_t j = i;
        while (current[j] == current[i]) {
            ++j;
        }
        size_t run = j - i;

        /* Write the run length in decimal, then the digit being counted. */
        int written = snprintf(next + pos, total - pos + 1, "%zu", run);
        if (written < 0) {
            perror("snprintf");
            exit(EXIT_FAILURE);
        }
        pos += (size_t)written;
        next[pos++] = current[i];
        i = j;
    }

    next[pos] = '\0';
    return next;
}

int main(void)
{
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    char *term = malloc(2);
    if (term == NULL) {
        perror("malloc");
        return EXIT_FAILURE;
    }
    strcpy(term, "1");

    for (int i = 0; i < n; ++i) {
        puts(term);

        /* Avoid computing an unneeded term after the last requested one. */
        if (i + 1 == n) {
            break;
        }

        char *following = next_term(term);
        free(term);
        term = following;
    }

    free(term);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* Read one line from stdin into a dynamically grown buffer. */
static char *read_one_line(void) {
    size_t cap = 64, len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) return NULL;

    int c;
    while ((c = fgetc(stdin)) != EOF && c != '\n') {
        /* Keep one byte free for the terminating '\0'. */
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                return NULL;
            }
            buf = tmp;
            cap = new_cap;
        }
        buf[len++] = (char)c;
    }

    /* Treat CRLF input the same as LF input. */
    if (len > 0 && buf[len - 1] == '\r') {
        --len;
    }
    buf[len] = '\0';
    return buf;
}

int main(void) {
    char *line = read_one_line();
    if (line == NULL) {
        fprintf(stderr, "out of memory\n");
        return EXIT_FAILURE;
    }

    size_t counts[256] = {0};

    /* Cast to unsigned char so byte values are valid array indices. */
    for (size_t i = 0; line[i] != '\0'; ++i) {
        ++counts[(unsigned char)line[i]];
    }

    size_t max_count = 0;
    for (size_t i = 0; i < 256; ++i) {
        if (counts[i] > max_count) {
            max_count = counts[i];
        }
    }

    if (max_count == 0) {
        /* Empty line: no character has a frequency. */
        putchar('\n');
        free(line);
        return 0;
    }

    /* Tie-break: choose the first character in the line with max_count. */
    char max_char = '\0';
    for (size_t i = 0; line[i] != '\0'; ++i) {
        if (counts[(unsigned char)line[i]] == max_count) {
            max_char = line[i];
            break;
        }
    }

    printf("%c %zu\n", max_char, max_count);
    free(line);
    return 0;
}

