/* Tricky part: define our own functions with the same int(int) signature
   as abs so they can all be used through one function pointer type. */
static int square(int x) { return x * x; }
static int negate(int x) { return -x; }

int main(void) {
    int cmd;

    /* Skip leading whitespace before the command character. */
    do {
        cmd = getchar();
    } while (cmd == ' ' || cmd == '\t' || cmd == '\n' || cmd == '\r');

    if (cmd == EOF) {
        return 0;
    }

    /* Select the operation through a function pointer. */
    int (*op)(int) = NULL;
    if (cmd == 'a') {
        op = abs;
    } else if (cmd == 's') {
        op = square;
    } else if (cmd == 'n') {
        op = negate;
    } else {
        fprintf(stderr, "unknown command: %c\n", cmd);
        return 1;
    }

    int value;
    /* Read every remaining integer until EOF and print its transformed value. */
    while (scanf("%d", &value) == 1) {
        printf("%d\n", op(value));
    }

    return 0;
}

