static int gcd(int a, int b) {
    int temporary;

    if (a < 0) {
        a = -a;
    }
    if (b < 0) {
        b = -b;
    }

    while (b != 0) {
        temporary = b;
        b = a % b;
        a = temporary;
    }

    return a;
}

