#include <stdio.h>
#include <stddef.h>

static unsigned long long multiply_modulo(unsigned long long left,
                                         unsigned long long right,
                                         unsigned long long modulus) {
    return (unsigned long long)((__int128)left * right % modulus);
}

static unsigned long long power_modulo(unsigned long long base,
                                      unsigned long long exponent,
                                      unsigned long long modulus) {
    unsigned long long result = 1 % modulus;
    base %= modulus;

    while (exponent > 0) {
        if (exponent & 1ULL) {
            result = multiply_modulo(result, base, modulus);
        }
        base = multiply_modulo(base, base, modulus);
        exponent >>= 1;
    }

    return result;
}

static int is_prime_number(unsigned long long number) {
    if (number < 2ULL) {
        return 0;
    }
    if (number == 2ULL || number == 3ULL) {
        return 1;
    }
    if (number % 2ULL == 0ULL) {
        return 0;
    }

    unsigned long long odd_part = number - 1ULL;
    int two_adic_exponent = 0;
    while ((odd_part & 1ULL) == 0ULL) {
        odd_part >>= 1;
        ++two_adic_exponent;
    }

    static const unsigned long long bases[] = {
        2ULL, 325ULL, 9375ULL, 28178ULL,
        450775ULL, 9780504ULL, 1795265022ULL
    };

    for (size_t i = 0; i < sizeof(bases) / sizeof(bases[0]); ++i) {
        unsigned long long base = bases[i] % number;
        if (base == 0ULL) {
            continue;
        }

        unsigned long long value = power_modulo(base, odd_part, number);
        if (value == 1ULL || value == number - 1ULL) {
            continue;
        }

        int is_composite = 1;
        for (int r = 1; r < two_adic_exponent; ++r) {
            value = multiply_modulo(value, value, number);
            if (value == number - 1ULL) {
                is_composite = 0;
                break;
            }
        }

        if (is_composite) {
            return 0;
        }
    }

    return 1;
}

int main(void) {
    long long input_number;

    if (scanf("%lld", &input_number) != 1) {
        return 0;
    }

    if (input_number < 2) {
        printf("0\n");
        return 0;
    }

    printf("%d\n", is_prime_number((unsigned long long)input_number));
    return 0;
}

