#define MAX_N 1000000

static bool is_composite[MAX_N + 1];

static void run_sieve(int limit)
{
    is_composite[0] = true;
    is_composite[1] = true;

    for (int candidate = 2; (long long)candidate * candidate <= limit; ++candidate) {
        if (!is_composite[candidate]) {
            for (int multiple = candidate * candidate; multiple <= limit; multiple += candidate) {
                is_composite[multiple] = true;
            }
        }
    }
}

static void print_primes(int limit)
{
    for (int value = 2; value <= limit; ++value) {
        if (!is_composite[value]) {
            printf("%d\n", value);
        }
    }
}

