{
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }

    if (n < 2) {
        return 0;
    }

    if (n > MAX_N) {
        n = MAX_N;
    }

    run_sieve(n);
    print_primes(n);

    return 0;
}

