static char *read_integer_token(void) {
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int character;
    do {
        character = getchar();
    } while (character != EOF && isspace((unsigned char)character));

    if (character == EOF) {
        free(buffer);
        return NULL;
    }

    while (character != EOF && !isspace((unsigned char)character)) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *grown_buffer = realloc(buffer, capacity);
