static long long reverse_digits(int value)
{
    int is_negative = value < 0;
    long long magnitude = is_negative ? -(long long)value : (long long)value;
    long long reversed = 0;

    while (magnitude > 0) {
        reversed = reversed * 10 + magnitude % 10;
        magnitude /= 10;
    }

    return is_negative ? -reversed : reversed;
}

