static int read_all_stdin(char **buffer, size_t *length) {
    size_t capacity = 4096;
    size_t used = 0;
    char *data = malloc(capacity);

    if (data == NULL) {
        return 0;
    }

    int character;
    while ((character = getchar()) != EOF) {
        if (used + 1 >= capacity) {
            if (capacity > SIZE_MAX / 2) {
                free(data);
                return 0;
            }
            size_t new_capacity = capacity * 2;
            char *resized = realloc(data, new_capacity);
            if (resized == NULL) {
                free(data);
                return 0;
            }
            data = resized;
            capacity = new_capacity;
        }
        data[used++] = (char)character;
    }

    if (ferror(stdin)) {
        free(data);
        return 0;
    }

    data[used] = '\0';
    *buffer = data;
    *length = used;
    return 1;
}

static char *extract_number(char *input) {
    while (isspace((unsigned char)*input)) {
        input++;
    }

    if (*input == '+') {
        input++;
    }

    if (!isdigit((unsigned char)*input)) {
        return NULL;
    }

    char *start = input;
    size_t length = strspn(start, "0123456789");
    char *after = start + length;

    while (isspace((unsigned char)*after)) {
        after++;
    }
    if (*after != '\0') {
        return NULL;
    }

    char *number = malloc(length + 1);
    if (number == NULL) {
        return NULL;
    }
    memcpy(number, start, length);
    number[length] = '\0';

    char *without_leading_zeros = number;
    while (without_leading_zeros[0] == '0' && without_leading_zeros[1] != '\0') {
        without_leading_zeros++;
    }

    if (without_leading_zeros != number) {
        size_t remaining = strlen(without_leading_zeros) + 1;
        memmove(number, without_leading_zeros, remaining);
    }

    return number;
}

static size_t count_set_bits(char *decimal) {
    size_t count = 0;

    while (!(decimal[0] == '0' && decimal[1] == '\0')) {
        if ((decimal[strlen(decimal) - 1] - '0') % 2 != 0) {
            count++;
        }

        int carry = 0;
        for (size_t i = 0; decimal[i] != '\0'; i++) {
            int current = carry * 10 + (decimal[i] - '0');
            decimal[i] = (char)('0' + current / 2);
            carry = current % 2;
        }

        size_t leading_zeros = 0;
        while (decimal[leading_zeros] == '0' && decimal[leading_zeros + 1] != '\0') {
            leading_zeros++;
        }
        if (leading_zeros > 0) {
            memmove(decimal, decimal + leading_zeros, strlen(decimal + leading_zeros) + 1);
        }
    }

    return count;
}

int main(void) {
    char *input = NULL;
    size_t input_length = 0;

    if (!read_all_stdin(&input, &input_length)) {
        fprintf(stderr, "error: could not read input\n");
        return EXIT_FAILURE;
    }

    char *number = extract_number(input);
    if (number == NULL) {
        fprintf(stderr, "error: expected a non-negative integer\n");
        free(input);
        return EXIT_FAILURE;
    }

    size_t set_bits = count_set_bits(number);
    printf("%zu\n", set_bits);

    free(number);
    free(input);
    return EXIT_SUCCESS;
}

