static long long totient(long long n)
{
    long long result = n;
    long long remaining = n;

    for (long long factor = 2; factor * factor <= remaining; factor++) {
        if (remaining % factor == 0) {
            while (remaining % factor == 0) {
                remaining /= factor;
            }
            result -= result / factor;
        }
    }

    if (remaining > 1) {
        result -= result / remaining;
    }

    return result;
}

