static int is_perfect_square(long long value)
{
    if (value < 0)
        return 0;
    if (value == 0)
        return 1;

    long long low = 1;
    long long high = 3037000500LL; /* greater than floor(sqrt(LLONG_MAX)) */

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        unsigned long long square =
            (unsigned long long)mid * (unsigned long long)mid;

        if (square == (unsigned long long)value)
            return 1;
        if (square < (unsigned long long)value)
            low = mid + 1;
        else
            high = mid - 1;
    }

    return 0;
}

