#include <stdio.h>
#include <stdlib.h>

typedef struct {
    char *characters;
    size_t length;
    int ended_with_newline;
} InputLine;

static int read_one_line(InputLine *line) {
    size_t capacity = 16;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return -1;
    }

    int character;
    while ((character = fgetc(stdin)) != EOF && character != '\n') {
        if (length + 1 > capacity) {
            size_t new_capacity = capacity * 2;
            if (new_capacity <= capacity) {
                free(buffer);
                return -1;
            }

            char *new_buffer = realloc(buffer, new_capacity);
            if (new_buffer == NULL) {
                free(buffer);
                return -1;
            }

            buffer = new_buffer;
            capacity = new_capacity;
        }

        buffer[length] = (char)character;
        ++length;
    }

    if (length == 0 && character == EOF) {
        free(buffer);
        return 0;
    }

    line->characters = buffer;
    line->length = length;
    line->ended_with_newline = (character == '\n');
    return 1;
}

static void reverse_characters(char *characters, size_t length) {
    for (size_t i = 0; i < length / 2; ++i) {
        char temporary = characters[i];
        characters[i] = characters[length - 1 - i];
        characters[length - 1 - i] = temporary;
    }
}

int main(void) {
    InputLine line;
    int read_status = read_one_line(&line);

    if (read_status == -1) {
        return EXIT_FAILURE;
    }

    if (read_status == 0) {
        return 0;
    }

    reverse_characters(line.characters, line.length);

    if (line.length > 0) {
        if (fwrite(line.characters, 1, line.length, stdout) != line.length) {
            free(line.characters);
            return EXIT_FAILURE;
        }
    }

    if (line.ended_with_newline) {
        if (fputc('\n', stdout) == EOF) {
            free(line.characters);
            return EXIT_FAILURE;
        }
    }

    free(line.characters);
    return 0;
}

