static void find_longest_word(const char *line, const char **word_start, size_t *word_length)
{
    *word_start = NULL;
    *word_length = 0;

    const char *position = line;
    while (*position != '\0') {
        while (*position != '\0' && isspace((unsigned char)*position)) {
            position++;
