#include <stdio.h>

#define LETTER_COUNT 26

static void count_letters(FILE *input, int counts[LETTER_COUNT]) {
    int character;

    while ((character = fgetc(input)) != EOF) {
        if (character >= 'a' && character <= 'z') {
            counts[character - 'a']++;
        }
    }
}

static void print_counts(const int counts[LETTER_COUNT]) {
    int is_first_entry = 1;

    for (int letter_index = 0; letter_index < LETTER_COUNT; ++letter_index) {
        if (counts[letter_index] == 0) {
            continue;
        }

        if (!is_first_entry) {
            putchar(' ');
        }

        printf("%c:%d", 'a' + letter_index, counts[letter_index]);
        is_first_entry = 0;
    }

    putchar('\n');
}

int main(void) {
    int counts[LETTER_COUNT] = {0};

    count_letters(stdin, counts);
    print_counts(counts);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stddef.h>

static char *read_one_line(size_t *line_length)
{
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int character;
    while ((character = fgetc(stdin)) != EOF && character != '\n') {
        if (length == capacity) {
            if (capacity > ((size_t)-1) / 2) {
                free(buffer);
                return NULL;
            }

            size_t new_capacity = capacity * 2;
            char *new_buffer = realloc(buffer, new_capacity);

            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }

            buffer = new_buffer;
            capacity = new_capacity;
        }

        buffer[length++] = (char)character;
    }

    if (ferror(stdin)) {
        free(buffer);
        return NULL;
    }

    char *final_buffer = realloc(buffer, length + 1);

    if (final_buffer == NULL) {
        free(buffer);
        return NULL;
    }

    buffer = final_buffer;
    buffer[length] = '\0';
    *line_length = length;
    return buffer;
}

static int write_sorted(const char *text, size_t length)
{
    int counts[256] = {0};

    for (size_t i = 0; i < length; i++) {
        counts[(unsigned char)text[i]]++;
    }

    for (int value = 0; value < 256; value++) {
        for (int count = 0; count < counts[value]; count++) {
            if (putchar(value) == EOF) {
                return 0;
            }
        }
    }

    return 1;
}

int main(void)
{
    size_t length = 0;
    char *line = read_one_line(&length);

    if (line == NULL) {
        return EXIT_FAILURE;
    }

    if (!write_sorted(line, length) || putchar('\n') == EOF) {
        free(line);
        return EXIT_FAILURE;
    }

    free(line);
    return EXIT_SUCCESS;
}

#include <ctype.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define BIGINT_BASE 1000000000u

typedef struct {
    uint32_t *digits;
    size_t count;
    size_t capacity;
} BigInt;

static void bigint_init(BigInt *number) {
    number->capacity = 8;
    number->digits = malloc(number->capacity * sizeof(uint32_t));
    if (!number->digits) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    number->digits[0] = 0;
    number->count = 1;
}

static void bigint_free(BigInt *number) {
    free(number->digits);
    number->digits = NULL;
    number->count = 0;
    number->capacity = 0;
}

static void bigint_grow(BigInt *number) {
    size_t new_capacity = number->capacity * 2;
    uint32_t *new_digits = realloc(number->digits, new_capacity * sizeof(uint32_t));
    if (!new_digits) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }
    number->digits = new_digits;
    number->capacity = new_capacity;
}

static void bigint_mul_small(BigInt *number, uint64_t factor) {
    uint64_t carry = 0;
    for (size_t i = 0; i < number->count; i++) {
        uint64_t product = (uint64_t)number->digits[i] * factor + carry;
        number->digits[i] = (uint32_t)(product % BIGINT_BASE);
        carry = product / BIGINT_BASE;
    }
    while (carry > 0) {
        if (number->count == number->capacity) {
            bigint_grow(number);
        }
        number->digits[number->count++] = (uint32_t)(carry % BIGINT_BASE);
        carry /= BIGINT_BASE;
    }
}

static void bigint_add_uint64(BigInt *number, uint64_t value) {
    uint64_t carry = value;
    size_t index = 0;
    while (carry > 0 && index < number->count) {
        uint64_t sum = (uint64_t)number->digits[index] + carry;
        number->digits[index] = (uint32_t)(sum % BIGINT_BASE);
        carry = sum / BIGINT_BASE;
        index++;
    }
    while (carry > 0) {
        if (number->count == number->capacity) {
            bigint_grow(number);
        }
        number->digits[number->count++] = (uint32_t)(carry % BIGINT_BASE);
        carry /= BIGINT_BASE;
    }
}

static void bigint_print(const BigInt *number) {
    size_t index = number->count;
    while (index > 0 && number->digits[index - 1] == 0) {
        index--;
    }
    if (index == 0) {
        putchar('0');
        return;
    }
    printf("%u", number->digits[index - 1]);
    while (index > 1) {
        index--;
        printf("%09u", number->digits[index - 1]);
    }
}

static int is_hex_digit(char c) {
    return (c >= '0' && c <= '9') ||
           (c >= 'a' && c <= 'f') ||
           (c >= 'A' && c <= 'F');
}

static int hex_digit_value(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    return c - 'A' + 10;
}

static uint64_t parse_hex_chunk(const char *text, size_t length) {
    uint64_t value = 0;
    for (size_t i = 0; i < length; i++) {
        value = value * 16 + (uint64_t)hex_digit_value(text[i]);
    }
    return value;
}

static char *read_all_stdin(void) {
    size_t capacity = 4096;
    size_t length = 0;
    char *buffer = malloc(capacity);
    if (!buffer) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    int ch;
    while ((ch = getchar()) != EOF) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *new_buffer = realloc(buffer, capacity);
            if (!new_buffer) {
                perror("realloc");
                exit(EXIT_FAILURE);
            }
            buffer = new_buffer;
        }
        buffer[length++] = (char)ch;
    }
    buffer[length] = '\0';
    return buffer;
}

int main(void) {
    char *input = read_all_stdin();
    const char *cursor = input;

    while (*cursor == ' ' || *cursor == '\t' || *cursor == '\r' || *cursor == '\n') {
        cursor++;
    }
    if (cursor[0] == '0' && (cursor[1] == 'x' || cursor[1] == 'X')) {
        cursor += 2;
    }

    const char *digits_start = cursor;
    while (is_hex_digit(*cursor)) {
        cursor++;
    }
    size_t digit_count = (size_t)(cursor - digits_start);

    BigInt number;
    bigint_init(&number);

    if (digit_count > 0) {
        size_t position = 0;
        size_t first_chunk_length = digit_count % 8;
        if (first_chunk_length == 0) {
            first_chunk_length = 8;
        }

        uint64_t first_value = parse_hex_chunk(digits_start, first_chunk_length);
        uint64_t first_base = 1;
        for (size_t i = 0; i < first_chunk_length; i++) {
            first_base *= 16;
        }
        bigint_mul_small(&number, first_base);
        bigint_add_uint64(&number, first_value);
        position += first_chunk_length;

        while (position < digit_count) {
            uint64_t chunk_value = parse_hex_chunk(digits_start + position, 8);
            bigint_mul_small(&number, 0x100000000ULL);
            bigint_add_uint64(&number, chunk_value);
            position += 8;
        }
    }

    bigint_print(&number);
    putchar('\n');

    bigint_free(&number);
    free(input);
    return 0;
}

