#include <stdio.h>
#include <stdlib.h>

static void bubble_sort(int *values, size_t count)
{
    for (size_t pass = 0; pass + 1 < count; ++pass) {
        int swapped = 0;

        for (size_t index = 0; index + 1 < count - pass; ++index) {
            if (values[index] > values[index + 1]) {
                int temporary = values[index];
                values[index] = values[index + 1];
                values[index + 1] = temporary;
                swapped = 1;
            }
        }

        if (!swapped) {
            break;
        }
    }
}

static void print_values(const int *values, size_t count)
{
    for (size_t index = 0; index < count; ++index) {
        if (index > 0) {
            putchar(' ');
        }
        printf("%d", values[index]);
    }
    putchar('\n');
}

int main(void)
{
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
        return EXIT_FAILURE;
    }

    int *values = NULL;
    if (count > 0) {
        values = malloc((size_t)count * sizeof *values);
        if (values == NULL) {
            return EXIT_FAILURE;
        }
    }

