#include <stdio.h>
#include <stdlib.h>

static void swap_numbers(int *first, int *second) {
    int temporary = *first;
    *first = *second;
    *second = temporary;
}

static int partition(int values[], int low, int high) {
    int pivot = values[low + (high - low) / 2];
    int left = low - 1;
    int right = high;

    while (1) {
        do {
            left++;
        } while (values[left] < pivot);

        do {
            right--;
        } while (values[right] > pivot);

        if (left >= right) {
            return right;
        }

        swap_numbers(&values[left], &values[right]);
    }
}

static void quicksort(int values[], int low, int high) {
    if (high - low < 2) {
        return;
    }

    int split = partition(values, low, high);
    quicksort(values, low, split + 1);
    quicksort(values, split + 1, high);
}

int main(void) {
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
