        for (int i = 0; i < count; i++) {
            if (scanf("%d", &values[i]) != 1) {
                free(values);
                return 1;
            }
        }
    }

    quicksort(values, 0, count);

    for (int i = 0; i < count; i++) {
        printf("%d", values[i]);
        if (i + 1 < count) {
            putchar(' ');
        } else {
            putchar('\n');
        }
    }

    free(values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static void merge_ranges(int *numbers, int *helper, size_t left, size_t middle, size_t right)
{
    size_t left_index = left;
    size_t right_index = middle + 1;
    size_t helper_index = left;

    while (left_index <= middle && right_index <= right) {
        if (numbers[left_index] <= numbers[right_index]) {
            helper[helper_index++] = numbers[left_index++];
        } else {
            helper[helper_index++] = numbers[right_index++];
        }
    }

    while (left_index <= middle) {
        helper[helper_index++] = numbers[left_index++];
    }

    while (right_index <= right) {
        helper[helper_index++] = numbers[right_index++];
    }

    for (size_t index = left; index <= right; ++index) {
        numbers[index] = helper[index];
    }
}

static void merge_sort_range(int *numbers, int *helper, size_t left, size_t right)
{
    if (left >= right) {
        return;
    }

    size_t middle = left + (right - left) / 2;
    merge_sort_range(numbers, helper, left, middle);
    merge_sort_range(numbers, helper, middle + 1, right);
    merge_ranges(numbers, helper, left, middle, right);
}

static void merge_sort(int *numbers, int *helper, size_t count)
{
    if (count > 1) {
        merge_sort_range(numbers, helper, 0, count - 1);
    }
}

int main(void)
{
    int count_input;

    if (scanf("%d", &count_input) != 1 || count_input < 0) {
