#include <stdio.h>
#include <stdlib.h>

static void swap_values(int *first, int *second)
{
    int temporary = *first;
    *first = *second;
    *second = temporary;
}

static void sift_down(int *values, size_t start, size_t end)
{
    size_t root = start;

    while (2 * root + 1 < end) {
        size_t child = 2 * root + 1;

        if (child + 1 < end && values[child] < values[child + 1]) {
            child++;
        }

        if (values[root] < values[child]) {
            swap_values(&values[root], &values[child]);
            root = child;
        } else {
            break;
        }
    }
}

static void heap_sort(int *values, size_t count)
{
    if (count < 2) {
        return;
    }

    for (size_t i = count / 2; i > 0; --i) {
        sift_down(values, i - 1, count);
    }

    for (size_t end = count; end > 1; --end) {
        swap_values(&values[0], &values[end - 1]);
        sift_down(values, 0, end - 1);
    }
}

int main(void)
{
