        for (int i = 0; i < count; ++i) {
            if (scanf("%d", &values[i]) != 1) {
                free(values);
                return 1;
            }
        }
    }

    int target;
    if (scanf("%d", &target) != 1) {
        free(values);
        return 1;
    }

    int found_index = binary_search(values, count, target);
    printf("%d\n", found_index);

    free(values);
    return 0;
}

#include <stdio.h>

static void update_top_two(long long value, long long *largest, long long *second_largest) {
    if (value > *largest) {
        *second_largest = *largest;
        *largest = value;
    } else if (value > *second_largest) {
        *second_largest = value;
    }
}

int main(void) {
    int count;

    if (scanf("%d", &count) != 1) {
        return 0;
    }

    if (count < 2) {
        for (int i = 0; i < count; i++) {
            long long ignored;
            scanf("%lld", &ignored);
        }
        return 0;
    }

    long long first_value;
    long long second_value;

    if (scanf("%lld", &first_value) != 1 || scanf("%lld", &second_value) != 1) {
        return 0;
    }

    long long largest;
    long long second_largest;

    if (first_value >= second_value) {
        largest = first_value;
        second_largest = second_value;
    } else {
        largest = second_value;
        second_largest = first_value;
    }

    for (int i = 2; i < count; i++) {
        long long value;

        if (scanf("%lld", &value) != 1) {
            return 0;
        }

        update_top_two(value, &largest, &second_largest);
    }

    printf("%lld %lld\n", largest, second_largest);
    return 0;
}
